# The controller/runner are imported with a write/process audit guard before any
# test/product module. The fixed probe permits reads needed by config later, but
# import itself must not call config, launch children, or mutate paths.
IMPORT_PROBE_PROGRAM = r'''
import os,sys
from pathlib import Path
if len(sys.argv)!=3:raise RuntimeError("CONTROLS SOURCE required")
controls,source=map(Path,sys.argv[1:]);sys.path.append(str(controls))
def audit(event,args):
 if event in ('subprocess.Popen','os.system','os.posix_spawn','os.fork','os.mkdir','os.remove','os.rename','os.chmod','os.rmdir','os.link','os.symlink','os.truncate','os.exec','os.forkpty'):
  raise RuntimeError('import side effect '+event)
 if event=='open' and len(args)>2 and isinstance(args[2],int) and args[2] & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC):
  raise RuntimeError('import write')
sys.addaudithook(audit)
import common
common.config=lambda *a,**k: (_ for _ in ()).throw(RuntimeError('import config execution'))
import controller,runner,observer
if any(n=='hv2ref' or n.startswith('hv2ref.') for n in sys.modules):raise RuntimeError('product import')
sys.path.insert(0,str(source/'tests'))
import test_entry_window_transition as factory_module
import unittest
if unittest.TestLoader().loadTestsFromModule(factory_module).countTestCases()!=0:raise RuntimeError('default factory leakage')
if any(n=='hv2ref' or n.startswith('hv2ref.') for n in sys.modules):raise RuntimeError('factory product import')
if set(controller.ENTRY_RUN_NAMES)!={m+'-'+s for m,slots in controller.ENTRY_MODE_SLOTS.items() for s in slots}:raise RuntimeError('slot drift')
print('CONTROL_IMPORT_PURE',os.getpgrp())
'''


RUNNER_FAILFAST_PROBE_PROGRAM = "# Fixed test-only runner orchestration probe. Real config/OLD admission first;\n# only synthetic discovery/selection metadata are substituted in this child.\nimport hashlib, json, os, sys, unittest\nfrom pathlib import Path\nfrom unittest import mock\nif len(sys.argv) != 6: raise RuntimeError('CONTROLS INPUT SHA OUT KIND required')\ncontrols, input_path, input_sha, out, kind = sys.argv[1:]\ncontrols = Path(controls); out = Path(out)\nif kind not in ('failure', 'error', 'subtest', 'success'): raise RuntimeError('probe kind')\nsys.path.append(str(controls))\nimport runner\nfrom common import canonical, config, digest, verify_old, read_json\nif Path(runner.__file__) != controls / 'runner.py': raise RuntimeError('runner identity')\nactual, paths = config(input_path, input_sha)\nverify_old(paths['old'], read_json(controls / 'baseline-inputs.json'))\nif not out.is_relative_to(paths['exec'] / 'runs') or not out.is_dir(): raise RuntimeError('probe output boundary')\nclass Probe(unittest.TestCase):\n    def setUp(self):\n        self.base = out / self._testMethodName\n        self.base.mkdir()\n        (self.base / 'before.bin').write_bytes(b'fixed synthetic failure preservation\\n')\n    def tearDown(self):\n        (out / ('cleanup-' + self._testMethodName)).write_bytes(b'cleanup completed\\n')\n    def test_01_selected(self):\n        if kind == 'failure': self.fail('EXPECTED_SYNTHETIC_FAILURE')\n        if kind == 'error': raise RuntimeError('EXPECTED_SYNTHETIC_ERROR')\n        if kind == 'subtest':\n            with self.subTest(fixed='first'):\n                self.fail('EXPECTED_SYNTHETIC_SUBTEST')\n            (out / 'continued-after-subtest').write_bytes(b'must not execute\\n')\n    def test_02_sentinel(self):\n        (out / 'second-test-started').write_bytes(b'normal success control only\\n')\nProbe.__module__ = 'runner_failfast_probe'; Probe.__qualname__ = 'Probe'\ntests = [Probe('test_01_selected'), Probe('test_02_sentinel')]\nids = [test.id() for test in tests]\nsynthetic = dict(actual, phase='base', factory=False, selection=ids)\ncollection = {'source_digest': actual['source_digest'], 'source_root_entries': actual['source_root_entries'],\n    'controls': actual['controls'], 'default_ids': ids, 'factory_ids': [],\n    'ordered': [{'id': name, 'occurrence': 1} for name in ids], 'duplicates': {}}\nsynthetic['collection_sha256'] = digest(canonical(collection))\ndef checked_fixture_config(path, sha):\n    if (path, sha) != (input_path, input_sha): raise RuntimeError('probe input mismatch')\n    current, current_paths = config(path, sha)\n    if current != actual or current_paths != paths: raise RuntimeError('probe admission drift')\n    return synthetic, paths\nwith mock.patch.object(runner, 'config', checked_fixture_config), mock.patch.object(unittest.TestLoader, 'discover', return_value=unittest.TestSuite(tests)):\n    sys.argv = [str(controls / 'runner.py'), input_path, input_sha, str(out), 'focused']\n    runner.main()\n"

OBSERVER_DIRFD_PROBE_PROGRAM = "# Fixed synthetic read/negative probes through the admitted actual observer.\n# Only the final product dispatch is substituted; config, hooks and faults run.\nimport errno, json, os, sys\nfrom pathlib import Path\nfrom unittest import mock\nif len(sys.argv) != 7: raise RuntimeError('CONTROLS INPUT SHA SCENARIO SHA KIND required')\ncontrols, inp, inp_sha, scenario, scenario_sha, kind = sys.argv[1:]\nif kind not in ('reads', 'mutation', 'paths', 'before', 'after'): raise RuntimeError('probe kind')\ncontrols = Path(controls); sys.path.append(str(controls))\nimport observer\nfrom common import config, digest, regular, read_json, require\nrequire(Path(observer.__file__) == controls / 'observer.py', 'observer identity')\nc, paths = config(inp, inp_sha)\nrequire(digest(regular(Path(scenario))) == scenario_sha, 'probe scenario drift')\ns = read_json(Path(scenario)); target = Path(s['target'])\nrequire(target.is_relative_to(paths['exec'] / 'runs'), 'probe target boundary')\noriginal_open, original_close = os.open, os.close\nparent = original_open(target, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)\nseen = []\ndef dispatch(entry, run_name):\n    require(entry == str(paths['source'] / 'colvia') and run_name == '__main__', 'fixed product dispatch')\n    flags = os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK\n    if kind in ('reads', 'before', 'after'):\n        operands = ('payload.bin', b'payload.bin', Path('payload.bin')) if kind == 'reads' else ('payload.bin',)\n        for operand in operands:\n            fd = os.open(operand, flags, dir_fd=parent)\n            try:\n                require(os.read(fd, 4096) == b'fixed-dirfd-read\\n', 'wrong descriptor-relative bytes')\n                require(os.fstat(fd).st_ino == (target / 'payload.bin').stat().st_ino, 'wrong descriptor inode')\n            finally: os.close(fd)\n        if kind == 'reads':\n            directory = os.open('nested', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent)\n            try:\n                leaf = os.open('child.bin', flags, dir_fd=directory)\n                try: require(os.read(leaf, 4096) == b'nested-dirfd-read\\n', 'nested bytes')\n                finally: os.close(leaf)\n            finally: os.close(directory)\n        print('READ_COMPLETED', flush=True)\n    elif kind == 'mutation':\n        cases = (os.O_WRONLY | os.O_NOFOLLOW, os.O_RDWR | os.O_NOFOLLOW,\n                 os.O_WRONLY | os.O_CREAT | os.O_NOFOLLOW,\n                 os.O_RDONLY | os.O_TRUNC | os.O_NOFOLLOW,\n                 os.O_RDONLY | os.O_APPEND | os.O_NOFOLLOW,\n                 os.O_RDONLY | os.O_NOFOLLOW | os.O_EXCL)\n        for value in cases:\n            try: fd = os.open('payload.bin', value, dir_fd=parent)\n            except RuntimeError as exc:\n                require(str(exc) == 'relative-fd read flags unsupported', 'unexpected flags refusal')\n                seen.append(value)\n            else:\n                os.close(fd); raise AssertionError('relative mutation unexpectedly admitted')\n        require(len(seen) == len(cases), 'missing mutation refusal')\n    else:\n        for value in ('.', '..', '../payload.bin', 'nested/child.bin', str(target / 'payload.bin'), ''):\n            try: fd = os.open(value, flags, dir_fd=parent)\n            except RuntimeError as exc:\n                require(str(exc) == 'relative-fd read component unsupported', 'unexpected component refusal')\n            else:\n                os.close(fd); raise AssertionError('unsupported component admitted')\n        try: fd = os.open('link.bin', flags, dir_fd=parent)\n        except OSError as exc: require(exc.errno == errno.ELOOP, 'nofollow error changed')\n        else:\n            os.close(fd); raise AssertionError('symlink followed')\n        try: fd = os.open('payload.bin', os.O_RDONLY, dir_fd=parent)\n        except RuntimeError as exc: require(str(exc) == 'relative-fd read flags unsupported', 'nofollow guard')\n        else:\n            os.close(fd); raise AssertionError('nofollow omission admitted')\n    return {}\ntry:\n    with mock.patch.object(observer.runpy, 'run_path', side_effect=dispatch):\n        sys.argv = [str(controls / 'observer.py'), inp, inp_sha, scenario, scenario_sha]\n        observer.main()\nfinally:\n    original_close(parent)\nprint(json.dumps({'kind': kind, 'pid': os.getpid(), 'pgid': os.getpgrp(), 'status': 'probe-complete'}))\n"

OBSERVER_BUFFERED_PROBE_PROGRAM = "# Fixed observer qualification; synthetic error modes are not product failure evidence.\nimport errno, fcntl, io, json, os, stat, sys\nfrom pathlib import Path\nfrom unittest import mock\nif len(sys.argv) != 7: raise RuntimeError('CONTROLS INPUT SHA SCENARIO SHA KIND required')\ncontrols=Path(sys.argv[1]);inp,inp_sha,scenario,scenario_sha,kind=sys.argv[2:]\nallowed={'normal','empty','one','large','multi','multi-raw','close-only','context-error','write-error','create-error','unsupported','bypass','identity-refusal','with-refusal','fdopen','fullsync','sync-error','sync-unavailable','mkdir-exists','fault'}\nif kind not in allowed: raise RuntimeError('fixed buffered probe kind')\nsys.path.insert(0,str(controls))\nimport observer\nfrom common import config,digest,regular,read_json,require\nrequire(Path(observer.__file__)==controls/'observer.py','observer identity')\nc,paths=config(inp,inp_sha);require(digest(regular(Path(scenario)))==scenario_sha,'probe scenario drift')\ns=read_json(Path(scenario));target=Path(s['target']);require(target.is_relative_to(paths['exec']/'runs'),'probe target boundary')\npath=target/'payload.bin';captured=[];native_open=io.open\npayload=b'' if kind=='empty' else b'x' if kind=='one' else bytes(range(251))*523 if kind=='large' else b'buffered-observation-payload-0123456789\\n'\n# Record the actual opener's object, preserving the arguments and return identity.\ndef capture(file,*args,**kwargs):\n    result=native_open(file,*args,**kwargs)\n    if isinstance(file,(str,bytes,os.PathLike)) and Path(file)==path:captured.append(result)\n    return result\nio.open=capture\nreport={'kind':kind,'pid':os.getpid(),'pgid':os.getpgrp(),'synthetic_error':kind in {'sync-error','sync-unavailable'}}\ndef dispatch(entry,run_name):\n    require(entry==str(paths['source']/'colvia') and run_name=='__main__','fixed dispatch')\n    if kind=='mkdir-exists':\n        try:(target/'existing').mkdir()\n        except FileExistsError as exc:require(exc.errno==errno.EEXIST,'mkdir exception changed')\n        else:raise AssertionError('existing directory recreated')\n        return {}\n    if kind=='bypass':\n        with native_open(path,'xb',buffering=256) as f:f.write(payload);f.flush()\n        return {}\n    if kind=='fdopen':\n        fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)\n        with os.fdopen(fd,'wb') as handle:\n            require(handle.write(payload)==len(payload),'fdopen write return')\n        report['unsupported_observation']='fdopen-wb'\n        return {}\n    if kind=='create-error':\n        try:path.open('xb')\n        except FileExistsError as exc:require(exc.errno==errno.EEXIST,'create exception changed')\n        else:raise AssertionError('existing file truncated')\n        require(not captured,'failed exclusive create returned a handle')\n        return {}\n    if kind=='unsupported':\n        try:path.open('xb',buffering=0)\n        except RuntimeError as exc:require(str(exc)=='exclusive binary handle type unsupported','unsupported handle reason')\n        else:raise AssertionError('unsupported handle observed as buffered')\n        require(len(captured)==1 and captured[0].closed,'unsupported handle leaked')\n        return {}\n    # Match the product's default buffering, with the same returned handle.\n    handle=path.open('xb')\n    require(len(captured)==1 and handle is captured[0],'returned object replaced or extra open')\n    require(type(handle) is io.BufferedWriter and type(handle.raw) is io.FileIO,'I/O object type changed')\n    raw=handle.raw;fd=handle.fileno();info=os.fstat(fd)\n    report['identity']={'fd':fd,'dev':info.st_dev,'ino':info.st_ino}\n    report['mode']=stat.S_IMODE(info.st_mode);report['payload_length']=len(payload)\n    def checked_write(data):\n        result=handle.write(data)\n        require(result==len(data),'buffered write return changed')\n        return result\n    if kind=='identity-refusal':\n        checked_write(payload);path.rename(target/'moved.bin')\n        try:handle.flush()\n        except RuntimeError as exc:require('witness unavailable:' in str(exc),'wrong witness failure')\n        else:raise AssertionError('renamed handle accepted')\n        try:handle.close()\n        except RuntimeError:pass\n        require(raw.closed,'refused handle leaked')\n        require((target/'moved.bin').read_bytes()==b'','refusal flushed pending data')\n        return {}\n    if kind=='with-refusal':\n        try:\n            with handle:\n                checked_write(payload);path.rename(target/'moved.bin')\n                handle.flush()\n        except RuntimeError as exc:require('witness unavailable:' in str(exc),'wrong with refusal')\n        else:raise AssertionError('renamed with handle accepted')\n        require(raw.closed,'with-refused handle leaked')\n        require((target/'moved.bin').read_bytes()==b'','with refusal flushed pending data')\n        return {}\n    if kind=='context-error':\n        try:\n            with handle:\n                checked_write(payload)\n                raise ValueError('EXPECTED_CONTEXT_ERROR')\n        except ValueError as exc:require(str(exc)=='EXPECTED_CONTEXT_ERROR','context exception changed')\n    else:\n        with handle:\n            if kind=='write-error':\n                try:handle.write('not bytes')\n                except TypeError:pass\n                else:raise AssertionError('invalid write accepted')\n                require(handle.tell()==0,'invalid write changed position')\n            elif kind=='multi':\n                for part in (payload[:3],payload[3:19],payload[19:]):checked_write(part)\n            elif kind=='multi-raw':\n                checked_write(payload);handle.flush();checked_write(payload)\n            else:checked_write(payload)\n            if kind not in {'close-only','write-error'}:handle.flush()\n            if kind in {'fullsync','fault','sync-error','sync-unavailable'}:\n                sys.path.insert(0,str(paths['source']/'src'))\n                from hv2ref.jsonio import _sync_fd\n                if kind=='sync-error':\n                    # Controlled error exercises _sync_fd's result mapping, not a native disk fault.\n                    observed_fcntl=fcntl.fcntl\n                    def synthetic_error(fd_,command,*args,**kwargs):\n                        if command==getattr(fcntl,'F_FULLFSYNC',None):raise OSError(errno.EIO,'synthetic fullfsync qualification')\n                        return observed_fcntl(fd_,command,*args,**kwargs)\n                    with mock.patch.object(fcntl,'fcntl',side_effect=synthetic_error):report['sync']=_sync_fd(fd)\n                elif kind=='sync-unavailable':\n                    with mock.patch.object(fcntl,'F_FULLFSYNC',None):report['sync']=_sync_fd(fd)\n                else:report['sync']=_sync_fd(fd)\n    require(handle.closed and raw.closed,'context did not close original objects')\n    require(not any(k in handle.__dict__ for k in ('write','flush','close')) and 'write' not in raw.__dict__,'seam reference cycle retained')\n    try:os.fstat(fd)\n    except OSError as exc:require(exc.errno==errno.EBADF,'closed descriptor error changed')\n    else:raise AssertionError('descriptor still open')\n    report['closed']=True\n    return {}\nwith mock.patch.object(observer.runpy,'run_path',side_effect=dispatch):\n    sys.argv=[str(controls/'observer.py'),inp,inp_sha,scenario,scenario_sha]\n    observer.main()\nreport['status']='probe-complete';print(json.dumps(report))\n"

OBSERVER_ERROR_PROBE_PROGRAM = "# Fixed qualification faults affect observer witnesses/logger only, never a product I/O fault claim.\nimport errno,fcntl,io,json,os,stat,sys\nfrom pathlib import Path\nfrom unittest import mock\nif len(sys.argv)!=7:raise RuntimeError('CONTROLS INPUT SHA SCENARIO SHA KIND required')\ncontrols=Path(sys.argv[1]);inp,inp_sha,scenario,scenario_sha,kind=sys.argv[2:]\nif kind not in {'witness-pre','witness-post','logger-pre','logger-post'}:raise RuntimeError('fixed error probe kind')\nsys.path.insert(0,str(controls))\nimport observer\nfrom common import config,digest,regular,read_json,require\nrequire(Path(observer.__file__)==controls/'observer.py','observer identity')\nc,paths=config(inp,inp_sha);require(digest(regular(Path(scenario)))==scenario_sha,'probe scenario drift')\ns=read_json(Path(scenario));target=Path(s['target']);events=Path(s['events']);path=target/'payload.bin'\nrequire(target.is_relative_to(paths['exec']/'runs'),'probe target boundary')\nnative_io_open=io.open;native_fstat=os.fstat;native_fsync=os.fsync;native_fcntl=fcntl.fcntl\nstate={'fired':False,'payload_fstat':0,'log_fd':None,'row':None,'captured':[]}\ndef named(fd):return os.fsdecode(native_fcntl(fd,fcntl.F_GETPATH,b'\\0'*1024).split(b'\\0',1)[0])\ndef capture(file,*args,**kwargs):\n handle=native_io_open(file,*args,**kwargs)\n if isinstance(file,(str,os.PathLike)) and Path(file)==events:\n  state['log_fd']=handle.fileno();write=handle.write\n  def log_write(text):\n   state['row']=json.loads(text);return write(text)\n  handle.write=log_write\n if isinstance(file,(str,os.PathLike)) and Path(file)==path:state['captured'].append(handle)\n return handle\ndef broken_fstat(fd):\n info=native_fstat(fd)\n if kind.startswith('witness') and stat.S_ISREG(info.st_mode) and named(fd)==str(path):\n  state['payload_fstat']+=1\n  wanted=1 if kind=='witness-post' else 2\n  if state['payload_fstat']==wanted:\n   state['fired']=True;raise OSError(errno.EIO,'synthetic observer witness')\n return info\ndef broken_fsync(fd):\n if kind.startswith('logger') and fd==state['log_fd'] and not state['fired']:\n  wanted='create-before' if kind=='logger-pre' else 'create-after'\n  if state['row'] and state['row']['event']==wanted:\n   state['fired']=True;raise OSError(errno.EIO,'synthetic observer log')\n return native_fsync(fd)\ndef dispatch(entry,run_name):\n require(entry==str(paths['source']/'colvia') and run_name=='__main__','fixed dispatch')\n with path.open('xb') as handle:\n  handle.write(b'must-not-reach-raw-write\\n');handle.flush()\n raise AssertionError('observer error was not raised')\nmessage=None\nwith mock.patch.object(io,'open',side_effect=capture),mock.patch.object(os,'fstat',side_effect=broken_fstat),mock.patch.object(os,'fsync',side_effect=broken_fsync),mock.patch.object(observer.runpy,'run_path',side_effect=dispatch):\n sys.argv=[str(controls/'observer.py'),inp,inp_sha,scenario,scenario_sha]\n try:observer.main()\n except RuntimeError as exc:message=str(exc)\n else:raise AssertionError('missing observer qualification error')\nrequire(state['fired'],'qualified seam not reached')\nrequire(message is not None and ('witness unavailable:' in message if kind.startswith('witness') else 'observer log unavailable:' in message),'wrong observer error')\nrequire(all(handle.closed for handle in state['captured']),'observer error leaked handle')\nprint(json.dumps({'kind':kind,'status':'expected-observer-error','message':message,'pid':os.getpid(),'pgid':os.getpgrp(),'synthetic_observer_fault':True,'captured':len(state['captured'])}))\n"

OLD_COUNTERPART_PROGRAM = "# Proposed fixed synthetic fixture child, not executed and not an acquisition path.\n# The only derived source delta is the fixed README suffix below. OLD stays sealed.\nimport hashlib, json, os, stat, sys\nfrom pathlib import Path\n\nif len(sys.argv) != 6:\n    raise RuntimeError('CONTROLS INPUT SHA TARGET COUNTERPART required')\ncontrols = Path(sys.argv[1]); input_path, input_sha = sys.argv[2:4]\ntarget, counterpart = map(Path, sys.argv[4:])\nsys.path.append(str(controls))\nfrom common import config, read_json, verify_old, regular, unlinked_path, require\nrequire(Path(sys.modules['common'].__file__) == controls / 'common.py', 'common import identity')\nc, paths = config(input_path, input_sha)\nrequire(c['phase'] == 'entry' and controls == paths['controls'], 'entry fixture context')\nimport controller as control_slots\nrequire(Path(control_slots.__file__) == controls / 'controller.py', 'controller import identity')\nrun_parts = target.relative_to(paths['exec'] / 'runs').parts\nrequire(len(run_parts) >= 3 and run_parts[0] in control_slots.ENTRY_RUN_NAMES and run_parts[1] == 'work', 'fixture run slot')\nwork = paths['exec'] / 'runs' / run_parts[0] / 'work'\nrequire(work.is_dir() and target != counterpart and target.is_relative_to(work) and counterpart.is_relative_to(work), 'fixture boundary')\nrequire(not target.is_relative_to(counterpart) and not counterpart.is_relative_to(target), 'fixture overlap')\nunlinked_path(target); unlinked_path(counterpart, exists=False)\nrequire(target.is_dir() and not list(target.iterdir()) and not counterpart.exists(), 'exclusive fixture destinations')\nrequire(not any((p / '.git').exists() for p in (target, *target.parents)), 'non-Git fixture topology')\nmanifest = read_json(controls / 'baseline-inputs.json')\nold = paths['old']; verify_old(old, manifest)\nsys.path.insert(0, str(old / 'src'))\nfrom hv2ref import product\nmembers = product.SERIAL_MANAGED_PATHS\nrequire(len(members) == 29 and 'hv2' in members and 'colvia' not in members, 'OLD membership')\nsuffix = b'\\nSynthetic OLD-window counterpart for P2 fence qualification.\\n'\nsource_rows = {}\nfor name in members:\n    info = manifest['files'][name]\n    data = regular(old / name)\n    require(len(data) == info['size'] and hashlib.sha256(data).hexdigest() == info['sha256'], 'OLD member drift')\n    derived = data + suffix if name == 'README.md' else data\n    destination = counterpart / name\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    with destination.open('xb') as handle:\n        handle.write(derived)\n    destination.chmod(0o755 if name == 'hv2' else 0o644)\n    source_rows[name] = {'source_sha256': info['sha256'], 'derived_sha256': hashlib.sha256(derived).hexdigest(), 'size': len(derived)}\nrequire([name for name, row in source_rows.items() if row['source_sha256'] != row['derived_sha256']] == ['README.md'], 'unexpected counterpart delta')\np = product.workspace_candidate(old); x = product.workspace_candidate(counterpart)\nrequire(p['release_ref'] != x['release_ref'] and p['inventory']['inventory_id'] == x['inventory']['inventory_id'] == 'checkout-1', 'distinct same-window source required')\nrequire(x['release_ref']['sha256'] == 'fad79ba1ba414435cd42e21c1e903d7c25eb10c8c3c20a83c3386e0cecc9d630', 'fixed counterpart digest')\nrequire(p['release_ref']['sha256'] == '8bd0eeac55fb0af92b61a7a36a98adb9957b880c791b957b20c319a51c5577f3', 'wrong audited predecessor')\n(target / 'a').write_bytes(b'preserved project content\\n')\nTIME = '2026-01-01T00:00:00Z'\ninit = product.workspace_init_preview(counterpart, target, authority_home_id='fixture-home', operation_id='fixture-x-init', created_at=TIME)\ninitialized = product.workspace_init_apply(counterpart, target, init['request'], confirm_token=init['confirm_token'])\nrequire(initialized['classification'] == 'initialized' and initialized['replayed'] is False, 'fixture init result')\nswitch = product.workspace_switch_preview(target, action='update', source=old, operation_id='fixture-to-predecessor', created_at=TIME)\nupdated = product.workspace_switch_apply(target, switch['request'], confirm_token=switch['confirm_token'], source=old)\nrequire(updated['classification'] == 'updated', 'fixture update result')\nstate = product.verify_workspace_product(target)\nbinding = json.loads(regular(target / '.hrn/product/binding.json'))\nrequire(binding['active_release'] == p['release_ref'] and binding['prior_release'] == x['release_ref'], 'fixture history must end at the audited predecessor')\nrequire(p['release_ref'] == {'id': 'product-release-8bd0eeac55fb0af92b61a7a3', 'sha256': '8bd0eeac55fb0af92b61a7a36a98adb9957b880c791b957b20c319a51c5577f3', 'inventory_id': 'checkout-1'}, 'exact P reference')\nrequire(x['release_ref'] == {'id': 'product-release-fad79ba1ba414435cd42e21c', 'sha256': 'fad79ba1ba414435cd42e21c1e903d7c25eb10c8c3c20a83c3386e0cecc9d630', 'inventory_id': 'checkout-1'}, 'exact X reference')\nrequire({member.name for member in target.iterdir()} == {'.hrn', 'a', 'hv2'}, 'fixture root membership')\nrequire(regular(target / 'a') == b'preserved project content\\n', 'fixture project content')\nrequire(regular(target / 'hv2') == regular(old / 'hv2') and stat.S_IMODE((target / 'hv2').stat().st_mode) == 0o755, 'fixture exact O')\nrequire({member.name for member in (target / '.hrn/product/receipts').iterdir()} == {'fixture-x-init.json', 'fixture-to-predecessor.json'}, 'fixture receipt membership')\nrequire({member.name for member in (target / '.hrn/product/releases').iterdir()} == {p['release_ref']['id'], x['release_ref']['id']}, 'fixture release membership')\nrequire(product.verify_workspace_release(target / '.hrn/product/releases' / x['release_ref']['id'])['release_ref'] == x['release_ref'], 'retained X release')\nrequire({member.relative_to(counterpart).as_posix() for member in counterpart.rglob('*') if member.is_file()} == set(members), 'counterpart membership')\nrequire({member.name for member in (target / '.hrn/staging').iterdir()} == {'init-fixture-x-init', 'switch-fixture-to-predecessor'}, 'history staging membership')\nrequire(all(member.is_dir() and not any(member.iterdir()) for member in (target / '.hrn/staging').iterdir()), 'history staging must be empty directories')\n# Keep X as candidate data only; it is not another admitted OLD executor.\n# Mode sealing prevents ordinary accidental writes, not hostile same-account mutation.\nfor name in members:\n    mode = 0o555 if name == 'hv2' else 0o444\n    (counterpart / name).chmod(mode); source_rows[name]['mode'] = mode\n# Directories stay writable for normal execution-tree retirement. Files are candidate data.\nrequire(all(stat.S_IMODE(directory.stat().st_mode) == 0o755 for directory in (counterpart, *(node for node in counterpart.rglob('*') if node.is_dir()))), 'counterpart directory mode')\nverify_old(old, manifest)\nfor name, row in source_rows.items():\n    require(hashlib.sha256(regular(counterpart / name)).hexdigest() == row['derived_sha256'] and stat.S_IMODE((counterpart / name).stat().st_mode) == row['mode'], 'counterpart drift')\nfor name, module in tuple(sys.modules.items()):\n    if name == 'hv2ref' or name.startswith('hv2ref.'):\n        require(Path(module.__file__).is_relative_to(old / 'src'), 'non-OLD product import')\nprint(json.dumps({'kind': 'synthetic-old-counterpart-history', 'pid': os.getpid(), 'pgid': os.getpgrp(),\n    'predecessor': p['release_ref'], 'counterpart': x['release_ref'], 'source_rows': source_rows,\n    'binding_ref': state['binding_ref'], 'binding': binding}, sort_keys=True))\n"

D3_SYNC_PROGRAM = "\n# Fixed child: instrument real sync aliases, then call the real CLI once.\n# No input-provided code, commands, imports or output paths are accepted.\nimport contextlib, errno, hashlib, io, json, os, stat, sys\nfrom pathlib import Path\nfrom unittest import mock\nif len(sys.argv) != 4: raise RuntimeError('SOURCE TARGET CANDIDATE required')\nsource, target, candidate = map(Path, sys.argv[1:])\nrequest = json.load(sys.stdin)\nif set(request) not in ({'preview', 'recover', 'selector', 'fault', 'truth_change'}, {'preview', 'recover', 'selector', 'fault', 'truth_change', 'verification_fault'}): raise RuntimeError('D3 request keys')\nverification_fault = request.get('verification_fault')\nif verification_fault not in (None, 'launcher-mode'): raise RuntimeError('D3 verification fault')\nif request['fault'] not in (None, 'unavailable', 'oserror'): raise RuntimeError('D3 fault')\nif type(request['recover']) is not bool or type(request['truth_change']) is not bool: raise RuntimeError('D3 booleans')\nsys.path.insert(0, str(source / 'src'))\nfrom hv2ref import product, workspace, jsonio, cli\npreview = request['preview']; plan = preview['request']; rid = plan['candidate_release']['id']; op = plan['operation_id']\nrelease = target / '.hrn/product/releases' / rid\nswitch = target / '.hrn/staging' / ('switch-' + op); staged = switch / rid\nbinding_stage = target / '.hrn/staging' / ('entry-' + op); next_binding = binding_stage / 'binding.next'\nreceipt = target / '.hrn/product/receipts' / (op + '.json')\nbinding = target / '.hrn/product/binding.json'\ndef tree():\n    result = {}\n    for path in sorted(target.rglob('*')):\n        st = path.lstat(); name = path.relative_to(target).as_posix()\n        if stat.S_ISLNK(st.st_mode): value = ['symlink', os.readlink(path)]\n        elif stat.S_ISDIR(st.st_mode): value = ['directory', stat.S_IMODE(st.st_mode)]\n        else:\n            if not stat.S_ISREG(st.st_mode) or st.st_nlink != 1: raise RuntimeError('special D3 fixture')\n            data = path.read_bytes(); value = ['file', stat.S_IMODE(st.st_mode), len(data), hashlib.sha256(data).hexdigest()]\n        result[name] = value\n    return result\nselectors = ('admission_root', 'admission_locks', 'receipt_parent', 'candidate_directory_parent',\n    'candidate_directory_self', 'candidate_member_parent', 'release_parent', 'release_operation_parent',\n    'new_entry_parent', 'old_retirement_parent', 'binding_directory_parent', 'binding_directory_self',\n    'binding_member_parent', 'binding_product_parent', 'binding_operation_parent', 'replay_release', 'recovery_release', 'same_entry_receipt',\n    'recovery_release_parent', 'recovery_operation_parent', 'recovery_new_parent', 'recovery_old_parent')\nD3_SITES = ('_entry_durable_directory', '_entry_write_exact', '_entry_sync_admission', '_entry_resync_release', '_entry_append_file', '_entry_replay_result', 'workspace_switch_apply')\nselector = request['selector']\nexact_selector = isinstance(selector, dict)\nif exact_selector:\n    if set(selector) != {'site', 'phase', 'role', 'path', 'occurrence'}: raise RuntimeError('exact D3 selector keys')\n    if selector['site'] not in D3_SITES: raise RuntimeError('exact D3 site')\n    if selector['phase'] not in ('admission', 'publication', 'recovery', 'replay'): raise RuntimeError('exact D3 phase')\n    if not all(isinstance(selector[k], str) and selector[k] for k in ('role', 'path')): raise RuntimeError('exact D3 names')\n    if selector['path'] != '.' and (selector['path'].startswith('/') or any(p in ('', '.', '..') for p in selector['path'].split('/'))): raise RuntimeError('exact D3 path')\n    if type(selector['occurrence']) is not int or selector['occurrence'] < 1: raise RuntimeError('exact D3 occurrence')\nelif selector not in (None, *selectors): raise RuntimeError('D3 selector')\nif (request['selector'] is None) != (request['fault'] is None): raise RuntimeError('D3 selector/fault pair')\nrows = []; hits = {}; injected = []; initial = tree()\nd3_stack = []; exact_hits = {}; instrumentation_errors = []; synthetic_changes = []\noriginal_entry_sync = product._entry_sync\ndef instrumentation_error(reason):\n    instrumentation_errors.append(reason)\n    raise RuntimeError('D3 instrumentation: ' + reason)\ndef identify_entry_sync(target, path, *, phase, role, b1=False):\n    frame = sys._getframe(1)\n    caller = frame.f_code.co_name\n    if caller not in D3_SITES or frame.f_globals.get('__name__') != 'hv2ref.product':\n        instrumentation_error('unmapped D3 caller')\n    context = {'site': caller, 'phase': phase, 'role': role, 'b1_arg': b1,\n               'sync_path': Path(path), 'sync_count': 0}\n    d3_stack.append(context)\n    try:\n        return original_entry_sync(target, path, phase=phase, role=role, b1=b1)\n    finally:\n        if context['sync_count'] != 1:\n            instrumentation_errors.append('D3 frame must delegate one sync')\n        if not d3_stack or d3_stack[-1] is not context:\n            instrumentation_errors.append('D3 frame stack mismatch')\n        else:\n            d3_stack.pop()\n\nif verification_fault is not None:\n    if not exact_selector or request['fault'] is None or request['truth_change']:\n        raise RuntimeError('compound D3 requires exact sync selector only')\n    if not (selector['site'] == '_entry_replay_result' and selector['phase'] == 'replay' or\n            selector['site'] == 'workspace_switch_apply' and selector['phase'] == 'publication' and\n            selector['role'] in {'binding-product-parent', 'binding-operation-parent'}):\n        raise RuntimeError('compound D3 is post-B1 only')\n\ndef break_launcher_mode():\n    # Fixed synthetic mutation; never changes a product helper or restores the target.\n    path = target / 'colvia'; before = tree()\n    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)\n    try:\n        opened = os.fstat(fd); named = path.lstat()\n        if not (stat.S_ISREG(opened.st_mode) and opened.st_nlink == named.st_nlink == 1 and\n                (opened.st_dev, opened.st_ino) == (named.st_dev, named.st_ino) and\n                stat.S_IMODE(opened.st_mode) == 0o755):\n            instrumentation_error('compound launcher precondition')\n        os.fchmod(fd, 0o600); os.fsync(fd)\n    finally:\n        os.close(fd)\n    after = tree(); expected = dict(before); expected['colvia'] = list(before['colvia']); expected['colvia'][1] = 0o600\n    if after != expected:\n        instrumentation_error('compound mutation changed more than launcher mode')\n    synthetic_changes.append({'kind': 'launcher-mode', 'before': before, 'after': after})\n\ndef facts():\n    return {'receipt': receipt.is_file(), 'staged': staged.is_dir(),\n            'inventory': (staged / 'inventory.json').is_file(), 'release': release.is_dir(),\n            'old': (target / 'hv2').is_file(),\n            'new_mode': stat.S_IMODE((target / 'colvia').stat().st_mode) if (target / 'colvia').is_file() else None,\n            'binding_directory': binding_stage.is_dir(),\n            'next_size': next_binding.stat().st_size if next_binding.is_file() else None,\n            'b1': json.loads(binding.read_bytes())['operation_id'] == op}\ninitial_facts = facts()\ndef matches(path, alias, s):\n    if alias != 'product':\n        return ['same_entry_receipt'] if alias == 'jsonio' and path == receipt.parent and s['receipt'] else []\n    options = {\n        'admission_root': path == target and not s['receipt'],\n        'admission_locks': path == target / '.hrn/locks' and not s['receipt'],\n        'receipt_parent': path == receipt.parent and s['receipt'] and not s['staged'] and not s['release'],\n        'candidate_directory_parent': path == switch and s['staged'] and not s['inventory'],\n        'candidate_directory_self': path == staged and not s['inventory'],\n        'candidate_member_parent': path == staged and s['inventory'],\n        'release_parent': path == release.parent and s['release'] and s['new_mode'] is None,\n        'release_operation_parent': path == switch and s['release'] and s['new_mode'] is None,\n        'new_entry_parent': path == target and s['new_mode'] == 0o755 and s['old'],\n        'old_retirement_parent': path == target and s['new_mode'] == 0o755 and not s['old'] and not s['b1'],\n        'binding_directory_parent': path == binding_stage.parent and s['binding_directory'] and s['next_size'] is None and not s['b1'],\n        'binding_directory_self': path == binding_stage and s['next_size'] is None and not s['b1'],\n        'binding_member_parent': path == binding_stage and s['next_size'] is not None and not s['b1'],\n        'binding_product_parent': path == binding.parent and s['b1'],\n        'binding_operation_parent': path == binding_stage and s['b1'] and s['next_size'] is None,\n        'replay_release': path == release and s['b1'],\n        # S5/B0: admission already visited release once; the existing receipt\n        # was then re-synced. Select the later recovery pass, not admission.\n        'recovery_release': request['recover'] and path == release\n            and initial_facts['receipt'] and initial_facts['release']\n            and initial_facts['new_mode'] == 0o755 and not initial_facts['old']\n            and not initial_facts['b1'] and not initial_facts['binding_directory']\n            and initial_facts['next_size'] is None and s == initial_facts\n            and sum(r['alias'] == 'product' and r['path'] == release.relative_to(target).as_posix() for r in rows) == 1\n            and sum(r['alias'] == 'product' and r['path'] == '.hrn/product/receipts' for r in rows) == 2\n            and max(i for i, r in enumerate(rows) if r['alias'] == 'product' and r['path'] == '.hrn/product/receipts')\n                > max(i for i, r in enumerate(rows) if r['alias'] == 'product' and r['path'] == release.relative_to(target).as_posix()),\n    }\n    # The fixed S5 fixture has no staging binding yet. Admission has already\n    # synced the existing receipt; its second product receipt sync starts recovery.\n    receipts = [i for i, r in enumerate(rows) if r['alias'] == 'product' and r['path'] == '.hrn/product/receipts' and not r['facts']['b1']]\n    in_recovery = (request['recover'] and initial_facts['release'] and initial_facts['receipt']\n        and not initial_facts['old'] and initial_facts['new_mode'] == 0o755\n        and not initial_facts['b1'] and not initial_facts['binding_directory']\n        and s == initial_facts and len(receipts) == 2)\n    if in_recovery:\n        root_syncs = sum(r['alias'] == 'product' and r['path'] == '.' for r in rows[receipts[-1] + 1:])\n        options.update(recovery_release_parent=path == release.parent,\n            recovery_operation_parent=path == switch,\n            recovery_new_parent=path == target and root_syncs == 0,\n            recovery_old_parent=path == target and root_syncs == 1)\n    return [name for name, yes in options.items() if yes]\ndef observe(alias, original):\n    def sync(path):\n        try:\n            path = Path(path); s = facts(); names = matches(path, alias, s)\n            for name in names: hits[name] = hits.get(name, 0) + 1\n            row = {'path': path.relative_to(target).as_posix(), 'alias': alias, 'facts': s,\n                   'selectors': names, 'occurrences': {name: hits[name] for name in names}}\n            observation = None\n            if alias == 'product':\n                direct_d3 = sys._getframe(1).f_code is original_entry_sync.__code__\n                if direct_d3 != bool(d3_stack):\n                    instrumentation_error('D3 wrapper bypass or unexpected nested sync')\n            if alias != 'product' and d3_stack:\n                instrumentation_error('non-product sync inside D3 frame')\n            if alias == 'product' and d3_stack:\n                current = d3_stack[-1]\n                current['sync_count'] += 1\n                if current['sync_count'] != 1 or path != current['sync_path']:\n                    instrumentation_error('D3 sync count/path mismatch')\n                identity = (current['site'], current['phase'], current['role'], row['path'])\n                exact_hits[identity] = exact_hits.get(identity, 0) + 1\n                observation = {**dict(zip(('site', 'phase', 'role', 'path'), identity)), 'occurrence': exact_hits[identity]}\n                row['d3'] = {**observation, 'b1_arg': current['b1_arg']}\n            else:\n                row['d3'] = None  # Observed non-D3 sync, not a D3 fault position.\n            selected = observation == selector if exact_selector else selector in names and hits[selector] == 1\n            rows.append(row)\n            if selected:\n                if verification_fault is not None:\n                    if not current['b1_arg'] or not s['b1']:\n                        instrumentation_error('compound injection before B1')\n                    row['pre_synthetic_facts'] = s\n                    break_launcher_mode()\n                    s = facts(); row['facts'] = s\n                injected.append({'index': len(rows) - 1, 'snapshot': tree(), 'facts': s})\n                row['result'] = request['fault']\n        except Exception as exc:\n            if instrumentation_errors:\n                raise\n            instrumentation_error('observer '+type(exc).__name__+': '+str(exc))\n        if selected:\n            if request['fault'] == 'oserror': raise OSError(errno.EIO, 'fixed D3 directory sync fault')\n            return 'unavailable:' + str(errno.EINVAL)\n        result = original(path); row['result'] = result; return result\n    return sync\ncompare = product._entry_compare_local; comparisons = []\ndef change_truth(root, **kwargs):\n    result = compare(root, **kwargs); comparisons.append(result)\n    draft = {'record_type': 'intent-draft', 'schema_version': 1, 'authority_home_id': 'fixture-home',\n        'intent_id': 'during-comparison', 'revision_id': 'during-draft', 'sequence': 1, 'prior_revision_ref': None,\n        'actor': 'agent', 'acceptance_authority': 'owner', 'observed_at': '2026-01-01T00:00:00Z',\n        'facets': {k: {'status': 'known', 'value': 'fixture'} for k in\n            ('acceptance_oracle', 'destination', 'expected_outcome', 'forbidden_scope', 'goal', 'scope')},\n        'gaps': [], 'statements': [], 'route': 'direct-entry'}\n    # Synthetic non-cooperating file mutation while the real guard stays held.\n    # Do not recursively invoke a writer or disable its guard.\n    home = root / '.hrn/intents/during-comparison'\n    home.mkdir(); (home / 'drafts').mkdir()\n    identity = {'record_type': 'intent-identity', 'schema_version': 1,\n                'authority_home_id': 'fixture-home', 'intent_id': 'during-comparison'}\n    for path, value in ((home / 'identity.json', identity), (home / 'drafts/during-draft.json', draft)):\n        with path.open('xb') as handle:\n            handle.write(jsonio.canonical_json_bytes(value)); handle.flush(); os.fsync(handle.fileno())\n    return result\nif request['truth_change'] and (request['selector'] is not None or not request['recover']): raise RuntimeError('D3 truth seam only for clean replay')\n# cli.main() receives parser arguments; the launcher alone consumes --source-checkout.\nargs = ['d3-fixed-cli', 'update', '--profile', 'entry-1', '--target', str(target),\n        '--source', str(candidate), '--apply', '--input', '-', '--confirm', preview['confirm_token']]\nif request['recover']: args.append('--recover')\noutput = io.StringIO(); errors = io.StringIO(); diagnostic = None\nwith contextlib.ExitStack() as stack:\n    stack.enter_context(mock.patch.object(product, '_entry_sync', identify_entry_sync))\n    for name, module in (('product', product), ('workspace', workspace), ('jsonio', jsonio)):\n        stack.enter_context(mock.patch.object(module, 'sync_directory', observe(name, module.sync_directory)))\n    if request['truth_change']: stack.enter_context(mock.patch.object(product, '_entry_compare_local', change_truth))\n    stack.enter_context(mock.patch.object(sys, 'argv', args))\n    stack.enter_context(mock.patch.object(sys, 'stdin', io.TextIOWrapper(io.BytesIO(jsonio.canonical_json_bytes(plan)))))\n    stack.enter_context(contextlib.redirect_stdout(output)); stack.enter_context(contextlib.redirect_stderr(errors))\n    try:\n        code = cli.main()\n    except SystemExit as exc:\n        code = exc.code if type(exc.code) is int else (0 if exc.code is None else 1)\n        diagnostic = {'kind': 'unexpected-SystemExit', 'message': str(exc)}\nif instrumentation_errors: raise RuntimeError('D3 instrumentation failure: ' + '; '.join(instrumentation_errors))\nif verification_fault is not None and len(synthetic_changes) != 1: raise RuntimeError('compound D3 mutation missing')\nif exact_selector and len(injected) != 1: raise RuntimeError('exact D3 selector was not injected exactly once')\ncli_exit = code\ntry:\n    parsed = json.loads(output.getvalue())\nexcept json.JSONDecodeError as exc:\n    parsed = None\n    if diagnostic is None:\n        diagnostic = {'kind': 'invalid-CLI-JSON', 'message': str(exc)}\n        code = 70\nif diagnostic is None and not isinstance(parsed, dict):\n    diagnostic = {'kind': 'invalid-CLI-result-shape', 'message': type(parsed).__name__}\n    code = 70\nvalue = {'exit': code, 'cli_exit': cli_exit, 'diagnostic': diagnostic, 'stdout': output.getvalue(),\n         'result': parsed, 'stderr': errors.getvalue(), 'rows': rows,\n         'injected': injected, 'synthetic_changes': synthetic_changes, 'before': initial, 'after': tree(), 'comparisons': comparisons}\nprint(json.dumps(value, sort_keys=True, separators=(',', ':')))\nraise SystemExit(code)\n"


def _validated_context(old_source, candidate_source, expected_predecessor, prefix_oracle, execution_context):
    need(isinstance(execution_context, MappingProxyType) and set(execution_context) == CONTEXT_FIELDS, 'readonly exact context required')
    ctx = dict(execution_context)
    need(type(ctx['schema']) is int and ctx['schema'] == 1 and ctx['phase'] == 'entry', 'context schema/phase')
    need(all(isinstance(ctx[k], str) for k in CONTEXT_FIELDS - {'schema', 'observer_command_prefix'}) and
         isinstance(ctx['observer_command_prefix'], tuple) and all(isinstance(x, str) for x in ctx['observer_command_prefix']), 'context types')
    import common
    import controller
    controls = common.unlinked_path(ctx['controls_dir'])
    need(Path(common.__file__) == controls / 'common.py' and Path(controller.__file__) == controls / 'controller.py', 'unverified control module')
    c, p = common.config(ctx['invocation_path'], ctx['invocation_sha256'])
    need(c['phase'] == 'entry' and c['factory'] is True, 'factory invocation phase')
    need(Path(old_source) == p['old'] and Path(candidate_source) == p['source'] and controls == p['controls'], 'factory source/context mismatch')
    need(expected_predecessor == common.read_json(controls / 'baseline-inputs.json') and
         prefix_oracle == common.read_json(controls / 'prefix-oracle.json'), 'factory control input mismatch')
    common.verify_old(p['old'], expected_predecessor)
    need(ctx['observer_sha256'] == c['controls']['observer.py'] and ctx['runtime_path'] == c['runtime']['path'] and
         ctx['runtime_sha256'] == c['runtime']['sha256'] and ctx['observer_command_prefix'] == tuple(common.python_command(c, p, 'observer.py')), 'derived context mismatch')
    work = common.unlinked_path(ctx['work_root'])
    need(work.is_dir() and work.name == 'work' and work.parent.name in controller.ENTRY_RUN_NAMES and
         work.parent.parent == p['exec'] / 'runs', 'factory WORK mismatch')
    need(tuple(expected_predecessor['literal_paths']['planning-1']) == OLD_PATHS and
         expected_predecessor['path_list_sha256']['planning-1'] == OLD_PATHS_SHA256, 'historical literal mismatch')
    need(tuple(item['id'] for item in prefix_oracle['steps']) == PREFIX_IDS, 'numbered prefix oracle mismatch')
    return MappingProxyType(ctx), c, p



