                self.assertEqual([('open-before', 'link.bin'), ('audit-before:open', 'link.bin')], [(r['event'], r['path']) for r in product_rows])
                refused=[r for r in rows if r['event']=='observer-refusal'];self.assertEqual(7,len(refused))
                self.assertEqual(['relative-fd read component unsupported']*6+['relative-fd read flags unsupported'],[r['detail']['reason'] for r in refused])
