        def buffered_probe(self, kind, *, event=None, length=None, occurrence=1):
            import errno
            target=self.directory('buffered-target-'+str(self.serial))
            if kind=='create-error':write_file(target/'payload.bin',b'preserved-existing\n')
            if kind=='mkdir-exists':(target/'existing').mkdir()
            before=snapshot(target)
            relative='existing' if kind=='mkdir-exists' else 'payload.bin'
            fault={'event':event,'path':relative,'occurrence':occurrence,'write_bytes':length} if event else None
            command,events,_,_,_=self.scenario(target,entry='new-source',
                argv=['--source-checkout','status','--target',target],fault=fault,pause=False)
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B','-c',OBSERVER_BUFFERED_PROBE_PROGRAM,
                paths['controls'],*command[-4:],kind),'observer-buffered')
            _,data=self.finish(child,log,timeout=60,expected=-signal.SIGKILL if fault else 0)
            rows=self.event_rows(events,allow_refusals=kind in {'unsupported','identity-refusal','with-refusal'})
            unit=b'' if kind=='empty' else b'x' if kind=='one' else bytes(range(251))*523 if kind=='large' else b'buffered-observation-payload-0123456789\n'
            payload=unit*2 if kind=='multi-raw' else unit
            if fault:
                self.assertEqual((event,relative),(rows[-1]['event'],rows[-1]['path']))
                self.assertEqual(occurrence,sum(r['event']==event and r['path']==relative for r in rows))
                if kind=='mkdir-exists':self.assertEqual(before,snapshot(target));return
                if event=='create-before':self.assertEqual(before,snapshot(target));return
                writes=[r for r in rows if r['event']=='raw-write-after' and r['path']==relative]
                written=sum(r['detail']['written'] for r in writes)
                self.assertLessEqual(written,len(payload));self.assertEqual(payload[:written],(target/'payload.bin').read_bytes())
                if event=='raw-write-after' and length is not None:self.assertEqual(length,writes[-1]['detail']['written'])
                if kind=='large' and event=='raw-write-after':self.assertIn('write',writes[-1]['detail']['within'])
                if kind=='multi-raw' and event=='raw-write-after' and occurrence==2:
                    self.assertEqual(len(unit)+(length if length is not None else len(unit)),written)
                if event=='buffered-flush-before' and occurrence==2:self.assertIn('close',rows[-1]['detail']['within'])
                self.assertEqual(0o644,stat.S_IMODE((target/'payload.bin').stat().st_mode))
                self.assertEqual({'payload.bin'},set(snapshot(target)))
                self.assert_all_write_audits(rows,complete=False)
                return
            result=json.loads(data.splitlines()[-1]);self.assertEqual('probe-complete',result['status'])
            self.assertEqual((child.pid,os.getpgrp()),(result['pid'],result['pgid']))
            if kind=='mkdir-exists':
                self.assertEqual(before,snapshot(target))
                self.assertEqual(['mkdir-before','audit-before:os.mkdir','mkdir-exists'],[r['event'] for r in rows]);return
            if kind=='create-error':
                self.assertEqual(before,snapshot(target))
                self.assertEqual(['create-before','audit-before:open'],[r['event'] for r in rows]);return
            if kind=='unsupported':
                self.assertEqual(b'',(target/'payload.bin').read_bytes())
                refused=[r for r in rows if r['event']=='observer-refusal'];self.assertEqual(1,len(refused))
                self.assertEqual({'site':'buffered-create','reason':'exclusive binary handle type unsupported','stage':'post-delegation'},refused[0]['detail'])
                self.assertFalse(any(r['event']=='raw-write-after' for r in rows));return
            if kind in {'identity-refusal','with-refusal'}:
                self.assertEqual({'moved.bin'},set(snapshot(target)));self.assertEqual(b'',(target/'moved.bin').read_bytes())
                refused=[r for r in rows if r['event']=='observer-refusal'];self.assertEqual(1,len(refused))
                self.assertEqual('buffered-flush',refused[0]['detail']['site']);self.assertEqual('pre-delegation',refused[0]['detail']['stage'])
                # Pre means this intercepted flush was not delegated; create/write already occurred.
                self.assertTrue(any(r['event']=='create-after' for r in rows));self.assertTrue(any(r['event']=='buffered-write-after' for r in rows))
                self.assertFalse(any(r['event'] in {'raw-write-before','raw-write-after','buffered-flush-before','buffered-close-before'} for r in rows));return
            if kind in {'bypass','fdopen'}:
                self.assertEqual(payload,(target/'payload.bin').read_bytes())
                self.assertTrue(any(r['event']=='audit-before:open' for r in rows))
                with self.assertRaises(AssertionError):self.assert_all_write_audits(rows)
                if kind=='fdopen':self.assertTrue(any(r['event']=='unobserved-open-after' for r in rows))
                return
            self.assertTrue(result['closed']);self.assertEqual(0o644,result['mode'])
            expected=b'' if kind=='write-error' else payload
            self.assertEqual(expected,(target/'payload.bin').read_bytes())
            self.assertEqual(0o644,stat.S_IMODE((target/'payload.bin').stat().st_mode))
            self.assert_all_write_audits(rows)
            if kind=='write-error':
                self.assertEqual(1,sum(r['event']=='buffered-write-before' for r in rows))
                self.assertFalse(any(r['event']=='buffered-write-after' for r in rows))
                self.assertFalse(any(r['event']=='raw-write-after' for r in rows))
                self.assertTrue(any(r['event']=='buffered-close-after' for r in rows));return
            self.assert_buffered_witness(rows,path='payload.bin',expected_length=len(expected),identity=result['identity'])
            if kind in {'fullsync','sync-error','sync-unavailable'}:
                self.assertEqual('pass',result['sync']['fsync'])
                if kind=='fullsync':
                    self.assertEqual('pass',result['sync']['fullfsync'],'T0 STOP: native fullfsync-after is not reachable')
                    self.assertEqual(1,sum(r['event']=='fullfsync-before' for r in rows))
                    self.assertEqual(1,sum(r['event']=='fullfsync-after' for r in rows))
                else:
                    self.assertTrue(result['synthetic_error'])
                    self.assertEqual('error:'+str(errno.EIO) if kind=='sync-error' else 'unavailable',result['sync']['fullfsync'])
                    self.assertFalse(any(r['event'] in {'fullfsync-before','fullfsync-after'} for r in rows))
            if kind=='multi':self.assertEqual(3,sum(r['event']=='buffered-write-before' for r in rows))
            if kind=='multi-raw':self.assertEqual(2,sum(r['event']=='raw-write-after' for r in rows))

