        def observer_error_probe(self,kind):
            target=self.directory('observer-error-target')
            command,events,_,_,_=self.scenario(target,entry='new-source',argv=['--source-checkout','status','--target',target],pause=False)
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B','-c',OBSERVER_ERROR_PROBE_PROGRAM,
                paths['controls'],*command[-4:],kind),'observer-error')
            _,data=self.finish(child,log,timeout=60)
            result=json.loads(data.splitlines()[-1]);self.assertEqual('expected-observer-error',result['status'])
            self.assertEqual((child.pid,os.getpgrp()),(result['pid'],result['pgid']));self.assertTrue(result['synthetic_observer_fault'])
            rows=self.event_rows(events,allow_refusals=True)
            if kind=='logger-pre':self.assertEqual({},snapshot(target));self.assertEqual(0,result['captured'])
            else:
                self.assertEqual({'payload.bin':('file',0o644,0,sha(b''))},snapshot(target));self.assertEqual(1,result['captured'])
            self.assertFalse(any(row['event'] in {'raw-write-before','raw-write-after'} for row in rows))
            stage='post-delegation' if kind.endswith('post') else 'pre-delegation'
            if kind.startswith('witness'):
                refusal=[row for row in rows if row['event']=='observer-refusal'];self.assertEqual(1,len(refusal))
                self.assertEqual(stage,refusal[0]['detail']['stage']);self.assertIn('witness unavailable:',refusal[0]['detail']['reason'])
            else:
                self.assertIn('stage='+stage,result['message']);self.assertFalse(any(row['event']=='observer-refusal' for row in rows))

