            self.bp_observe(target,source=candidate_source);self.bp_observe(target)
            d=self.bp_draft('bp-checkout-writer');g=self.bp_cli(target,['intent','draft'],value=d)
            self.assertEqual(d,g['drafts'][d['revision_id']]);self.bp_lifecycle_refusals(target)

