        def test_four_executor_entry_boundaries(self):
            target = self.old_target(); preview = self.transition(target)
            # Explicit trusted sources both read S0. The installed NEW entry does
            # not exist at S0; its absence is not a writer-fence success.
            before = snapshot(target)
            for selector in ('old-source', 'new-source', 'installed-old'):
                args = ['status'] if selector.startswith('installed') else ['--source-checkout', 'status', '--target', target]
                code, data, _ = self.call(target, args, entry=selector)
                self.assertEqual(0, code, data); self.assertEqual('pass', json.loads(data)['classification'])
                self.assertEqual(before, snapshot(target))
            self.assertFalse((target / 'colvia').exists())
            # Source mode does not expose installed record commands. Count its
            # parser refusal separately from a valid writer under a guard.
            for selector in ('old-source', 'new-source'):
                for family in ('intent', 'work', 'candidate'):
                    action = {'intent': 'draft', 'work': 'publish', 'candidate': 'add'}[family]
                    code, data, _ = self.call(target, ['--source-checkout', family, action, '--target', target], {}, entry=selector)
                    self.assertEqual(2, code, data); self.assertIn(b'invalid choice', data)
                    self.assertEqual(before, snapshot(target))
            self.interrupted_api(target, preview, 'after-launcher'); before = snapshot(target)
            self.assertFalse((target / 'hv2').exists()); self.assertTrue((target / 'colvia').is_file())
            code, data, _ = self.call(target, ['status'], entry='installed-new')
            self.assertEqual(65, code, data); self.assertEqual('HV2-WORKSPACE-LAUNCHER', json.loads(data)['code'])
            self.assertEqual(before, snapshot(target))
            code, data, _ = self.call(target, self.apply_args(target, preview, recover=True), preview['request'])
            self.assertEqual(0, code, data)
            before = snapshot(target)
            for selector in ('new-source', 'installed-new'):
                args = ['status'] if selector == 'installed-new' else ['--source-checkout', 'status', '--target', target]
                code, data, _ = self.call(target, args, entry=selector)
                self.assertEqual(0, code, data); self.assertEqual('pass', json.loads(data)['classification'])
                self.assertEqual(before, snapshot(target))
            self.assertFalse((target / 'hv2').exists())

        def p2_materials(self,target,preview,*,strict=True):
            product=self.product();candidate=product.workspace_candidate(candidate_source)
            self.assertEqual(P2_RELEASE_ID,candidate['release_ref']['id'])
            self.assertEqual(P2_RELEASE_SHA,candidate['release_ref']['sha256'])
            prior=json.loads((target/'.hrn/product/binding.json').read_bytes())
            b1={'record_type':'product-binding','schema_version':1,'authority_home_id':prior['authority_home_id'],
                'active_release':candidate['release_ref'],'prior_release':prior['active_release'],'operation_id':'entry-transition'}
            receipt={'record_type':'lifecycle-receipt','schema_version':2,'operation_id':'entry-transition','plan':preview['request'],
                'prior_binding_ref':ref(prior,'operation_id'),'result_binding_ref':ref(b1,'operation_id')}
            self.assertEqual(preview['request']['expected_binding_ref'],receipt['prior_binding_ref'])
            staged='.hrn/staging/switch-entry-transition/'+P2_RELEASE_ID
            files={'.hrn/product/receipts/entry-transition.json':canonical(receipt),staged+'/inventory.json':canonical(candidate['inventory'])}
            files.update({staged+'/payload/'+name:data for name,data in candidate['payload'].items()})
            if strict:self.assertEqual(P2_A1_LENGTHS,{name:len(data) for name,data in files.items()})
            self.assertEqual(P2_BINDING_LENGTH,len(canonical(b1)))
            return candidate,files,canonical(b1)

        def p2_complete_snapshot(self,initial,files,candidate,b1):
            expected=dict(initial);staged='.hrn/staging/switch-entry-transition/'+P2_RELEASE_ID
            release='.hrn/product/releases/'+P2_RELEASE_ID
            for name,data in files.items():
                name=release+name[len(staged):] if name.startswith(staged+'/') else name
                for parent in Path(name).parents:
                    if str(parent)!='.':expected.setdefault(parent.as_posix(),('directory',0o755))
                expected[name]=('file',0o644,len(data),sha(data))
            expected['.hrn/staging/switch-entry-transition']=('directory',0o755)
            expected['.hrn/staging/entry-entry-transition']=('directory',0o755)
            expected.setdefault('.hrn/locks/writer.lock',('file',0o600,0,sha(b'')))
            expected.pop('hv2',None)
            expected['colvia']=('file',0o755,len(candidate['payload']['colvia']),sha(candidate['payload']['colvia']))
            expected['.hrn/product/binding.json']=('file',0o600,len(b1),sha(b1))
            return expected

        def p2_a1_case(self,index):
            spec=P2_A1_ROWS[index];product=self.product();target=self.old_target();preview=self.transition(target)
            initial=snapshot(target);root_mode=stat.S_IMODE(target.lstat().st_mode)
            candidate,files,b1=self.p2_materials(target,preview)
            request_bytes=canonical(preview['request']);token=preview['confirm_token']
            fault={key:spec[key] for key in ('event','path','occurrence','write_bytes')}
            code,data,events=self.call(target,self.apply_args(target,preview),preview['request'],fault=fault)
            self.assertEqual(-signal.SIGKILL,code,data[-8000:]);self.assertTrue(events.read_bytes().endswith(b'\n'))
            rows=self.event_rows(events);last=rows[-1]
            self.assertEqual((spec['event'],spec['path']),(last['event'],last['path']))
            self.assertEqual(spec['occurrence'],sum((r['event'],r['path'])==(spec['event'],spec['path']) for r in rows))
            self.assertEqual(self.children[-1].pid,last['pid']);self.assertTrue(all(r['pid']==last['pid'] for r in rows))
            self.assert_all_write_audits(rows,complete=False)
            expected=dict(initial);expected.setdefault('.hrn/locks/writer.lock',('file',0o600,0,sha(b'')))
            for name in spec['added_directories']:expected[name]=('directory',0o755)
            for name in spec['prior_complete_files']:
                raw=files[name];expected[name]=('file',0o644,len(raw),sha(raw))
            current=spec['current_member'];written=None
            if current is not None and spec['current_exists']:
                writes=[r for r in rows if r['path']==current and r['event']=='raw-write-after']
                written=sum(r['detail']['written'] for r in writes)
                self.assertLessEqual(written,len(files[current]))
                for row in writes:self.assertGreater(row['detail']['written'],0)
                raw=files[current][:written];expected[current]=('file',0o644,len(raw),sha(raw))
                if spec['write_bytes'] is not None:
                    self.assertEqual(spec['write_bytes'],written);self.assertEqual(spec['write_bytes'],last['detail']['written'])
                if spec['event']=='raw-write-after' and spec['write_bytes'] is None:self.assertEqual(len(files[current]),written)
            after=snapshot(target);self.assertEqual(expected,after,'exact physical prefix and B0/truth preservation')
            self.assertEqual(root_mode,stat.S_IMODE(target.lstat().st_mode));self.assert_lock_free(target)
            self.assertEqual(request_bytes,canonical(preview['request']));self.assertEqual(token,preview['confirm_token'])
            self.assertEqual(candidate['release_ref'],product.workspace_candidate(candidate_source)['release_ref'])
            torn=current is not None and spec['current_exists'] and written<len(files[current])
            receipt_present='.hrn/product/receipts/entry-transition.json' in after
            code,data,recovery_events=self.call(target,self.apply_args(target,preview,recover=receipt_present),preview['request'])
            result=json.loads(data)
            if torn:
                self.assertEqual(65,code,data)
                if current=='.hrn/product/receipts/entry-transition.json':
                    self.assertIn(result['code'],('HV2-JSON-EOF','HV2-JSON-SYNTAX','HV2-JSON-NONCANONICAL'))
                else:
                    self.assertEqual('HV2-WORKSPACE-PRODUCT',result['code'])
                    self.assertEqual('torn or changed init bytes: '+current.split(P2_RELEASE_ID+'/',1)[1],result['message'])
                self.assertEqual(after,snapshot(target),'unsupported torn prefix must stay byte/mode exact')
                prohibited=('create-after','raw-write-after','write-after','rename-after','replace-after','unlink-after','fchmod-after','chmod-after')
                self.assertFalse(any(row['event'] in prohibited for row in self.event_rows(recovery_events)))
            else:
                self.assertEqual(0,code,data);self.assertEqual('updated',result['classification'])
                completed=self.p2_complete_snapshot(initial,files,candidate,b1)
                self.assertEqual(completed,snapshot(target));self.assertEqual('entry-transition',product.verify_workspace_product(target)['binding_ref']['id'])
                self.assertEqual(completed,snapshot(target))
                code,data,_=self.call(target,self.apply_args(target,preview,recover=True),preview['request'])
                self.assertEqual(0,code,data);self.assertEqual('replayed',json.loads(data)['classification']);self.assertEqual(completed,snapshot(target))
            self.assertEqual(root_mode,stat.S_IMODE(target.lstat().st_mode));self.assertEqual(initial['a'],snapshot(target)['a'])

        def test_p2_t0_actual_member_trace_and_d3_map(self):
            target=self.old_target();preview=self.transition(target);initial=snapshot(target)
            candidate,files,b1=self.p2_materials(target,preview)
            code,data,events=self.call(target,self.apply_args(target,preview),preview['request'])
            self.assertEqual(0,code,data);rows=self.event_rows(events);self.assert_all_write_audits(rows)
            self.assertEqual(self.p2_complete_snapshot(initial,files,candidate,b1),snapshot(target))
            for path,raw in files.items():
                self.assert_buffered_witness(rows,path=path,expected_length=len(raw))
                subset=[r for r in rows if r['path']==path]
                self.assertEqual(1,sum(r['event']=='raw-write-after' for r in subset),'T0 STOP: raw multiplicity differs')
                for event,count in (('buffered-write-before',1),('buffered-write-after',1),('buffered-flush-before',2),('buffered-flush-after',2),('buffered-close-before',1),('buffered-close-after',1),('fullfsync-before',1),('fullfsync-after',1)):
                    self.assertEqual(count,sum(r['event']==event for r in subset),'T0 STOP: '+path+' '+event)
            for spec in P2_A1_ROWS:
                hits=[r for r in rows if (r['event'],r['path'])==(spec['event'],spec['path'])]
                self.assertGreaterEqual(len(hits),spec['occurrence'],'T0 STOP: missing physical selector')
            # A separate independently initialized target verifies the exact D3 trace.
