            self.assertEqual(complete,snapshot(target));self.assert_lock_free(target)
            self.assertEqual('entry-transition',self.product().verify_workspace_product(target)['binding_ref']['id'])
            self.assertEqual(complete,snapshot(target));self.assertEqual(initial['a'],prepared['a'])

