        def p2_state_snapshot(self,initial,files,candidate,b1,label):
            model=P2_D3_STATES[P2_A2_STATE_MODELS[label]];expected=dict(initial)
            staged='.hrn/staging/switch-entry-transition/'+P2_RELEASE_ID;release='.hrn/product/releases/'+P2_RELEASE_ID
            if '.hrn/staging' not in model['dirs']:
                for name in tuple(expected):
                    if name=='.hrn/staging' or name.startswith('.hrn/staging/'):del expected[name]
            for directory in model['dirs']:
                if directory!='.':expected.setdefault(directory,('directory',0o755))
            if model['receipt']:
                raw=files['.hrn/product/receipts/entry-transition.json'];expected['.hrn/product/receipts/entry-transition.json']=('file',0o644,len(raw),sha(raw))
            for name in model['files']:
                raw=files[staged+'/'+name];location=(release if model['release'] else staged)+'/'+name
                expected[location]=('file',0o644,len(raw),sha(raw))
            if model['new']:
                data=candidate['payload']['colvia'];size=0 if label=='S3a' else len(data)
                expected['colvia']=('file',0o600 if label in {'S3a','S3b'} else 0o755,size,sha(data[:size]))
            if not model['old']:del expected['hv2']
            if model['binding']:expected['.hrn/staging/entry-entry-transition/binding.next']=('file',0o600,1,sha(b1[:1]))
            if model['b1']:expected['.hrn/product/binding.json']=('file',0o600,len(b1),sha(b1))
            return expected

        def p2_prepare_state(self,label,name='target'):
            self.assertIn(label,P2_A2_STATE_MODELS)
            target=self.old_target(name);preview=self.transition(target);initial=snapshot(target)
            candidate,files,b1=self.p2_materials(target,preview)
            if label=='S0':pass
            elif label=='S1':self.interrupted_api(target,preview,'after-receipt')
            elif label=='S2-full':self.interrupted_api(target,preview,'after-staged-payload')
            elif label.startswith('S2-mkdir:'):
                path=label.split(':',1)[1];fault={'event':'mkdir-after','path':path,'occurrence':1,'write_bytes':None}
                code,data,events=self.call(target,self.apply_args(target,preview),preview['request'],fault=fault)
                self.assertEqual(-signal.SIGKILL,code,data);self.assertEqual(('mkdir-after',path),(self.event_rows(events)[-1]['event'],self.event_rows(events)[-1]['path']))
            elif label in {'S3','S3a','S3b','S4','S3-fallback-staging','S3-fallback-home'}:
                self.interrupted_api(target,preview,'after-release')
                if label in {'S3a','S3b','S4'}:
                    event,path,length=('open-after','colvia',None) if label=='S3a' else ('write-after','colvia',None) if label=='S3b' else ('unlink-before','hv2',None)
                    fault={'event':event,'path':path,'occurrence':1,'write_bytes':length}
                    code,data,events=self.call(target,self.apply_args(target,preview,recover=True),preview['request'],fault=fault)
                    self.assertEqual(-signal.SIGKILL,code,data);last=self.event_rows(events)[-1];self.assertEqual((event,path),(last['event'],last['path']))
            elif label in {'S5','S5-binding-prefix'}:
                self.interrupted_api(target,preview,'after-launcher')
                if label=='S5-binding-prefix':
                    path='.hrn/staging/entry-entry-transition/binding.next';fault={'event':'write-after','path':path,'occurrence':1,'write_bytes':1}
                    code,data,events=self.call(target,self.apply_args(target,preview,recover=True),preview['request'],fault=fault)
                    self.assertEqual(-signal.SIGKILL,code,data);last=self.event_rows(events)[-1];self.assertEqual(('write-after',path),(last['event'],last['path']));self.assertEqual(1,(target/path).stat().st_size)
            elif label.startswith('S6-'):self.interrupted_api(target,preview,'after-binding')
            else:self.fail('undeclared P2 state')
            # Explicit retirement of only independently checked empty synthetic staging directories.
            retire=[]
            if label in {'S3-fallback-staging','S3-fallback-home','S6-operation-retired','S6-staging-retired'}:retire.append('.hrn/staging/switch-entry-transition')
            if label in {'S6-operation-retired','S6-staging-retired'}:retire.append('.hrn/staging/entry-entry-transition')
            if label in {'S3-fallback-home','S6-staging-retired'}:retire.extend(('.hrn/staging/init-fixture-init','.hrn/staging'))
            for path in retire:
                directory=target/path;self.assertEqual([],list(directory.iterdir()));directory.rmdir()
            self.assertEqual(self.p2_state_snapshot(initial,files,candidate,b1,label),snapshot(target),'independent exact starting state')
            return target,preview,initial,candidate,files,b1

        def p2_assert_sync_prefix(self,target,snap,initial,candidate,files,b1):
            # Independent finite namespace/value predicate, not the child's own snapshot as oracle.
            staged='.hrn/staging/switch-entry-transition/'+P2_RELEASE_ID;release='.hrn/product/releases/'+P2_RELEASE_ID
            known=dict(initial);full=self.p2_complete_snapshot(initial,files,candidate,b1);known.update(full)
            for name,raw in files.items():
                known[name]=('file',0o644,len(raw),sha(raw))
                for parent in Path(name).parents:
                    if str(parent)!='.':known.setdefault(parent.as_posix(),('directory',0o755))
            next_path='.hrn/staging/entry-entry-transition/binding.next';known[next_path]=('file',0o600,len(b1),sha(b1))
            self.assertTrue(set(snap)<=set(known),'unexpected prefix path')
            for name,value in snap.items():
                if name in {'colvia',next_path,'.hrn/product/binding.json'}:
                    allowed={known[name]}
                    if name in initial:allowed.add(initial[name])
                    self.assertIn(value,allowed,name)
                else:self.assertEqual(known[name],value,name)
            for name,value in initial.items():
                if name in {'hv2','colvia',next_path,'.hrn/product/binding.json'} or name=='.hrn/staging' or name.startswith('.hrn/staging/'):continue
                self.assertEqual(value,snap[name],name)
            if release in snap:
                self.assertFalse(any(name==staged or name.startswith(staged+'/') for name in snap))
                for name,raw in files.items():
                    if name.startswith(staged+'/'):
                        location=release+name[len(staged):];self.assertEqual(('file',0o644,len(raw),sha(raw)),snap[location],location)
            if snap['.hrn/product/binding.json']==('file',0o600,len(b1),sha(b1)):
                self.assertNotIn('hv2',snap);self.assertNotIn(next_path,snap);self.assertEqual(full['colvia'],snap['colvia'])
            for name in snap:
                for parent in Path(name).parents:
                    if str(parent)!='.':self.assertIn(parent.as_posix(),snap)
            self.assertEqual(snap,snapshot(target),'assertion reads mutated the prefix')

        def p2_a2_case(self,index,*,legacy=None):
            import errno
            spec=P2_A2_ROWS[index];label=spec['state'];target,preview,base,candidate,files,b1=self.p2_prepare_state(label)
            prepared=snapshot(target);model=P2_D3_STATES[P2_A2_STATE_MODELS[label]]
            selector=spec['selector'];fault=spec['fault'];exact={key:selector[key] for key in ('site','phase','role','path','occurrence')}
            if spec['kind']=='verification-unavailable':
                self.fail('compound cells use the separate declared helper')
            changed=spec['kind']=='changed-truth-precedence'
            if changed:
                self.assertTrue(model['b1']);self.d3_new_truth(target);prepared=snapshot(target)
            recover=model['receipt'];result=self.d3_run(target,preview,selector=legacy or exact,fault=fault,recover=recover)
            self.assertEqual(65,result['exit']);self.assertEqual('HV2-WORKSPACE-PRODUCT',result['result']['code'])
            expected_token='d3-sync:'+selector['phase']+':'+selector['role']
            self.assertTrue(result['result']['message'].startswith(expected_token+';'))
            self.assertIn('directory synchronization '+('unavailable:'+str(errno.EINVAL) if fault=='unavailable' else 'oserror:'+str(errno.EIO)),result['result']['message'])
            self.assertIn('B1 publication observed='+('yes' if selector['b1_arg'] else 'no'),result['result']['message'])
            self.assertIn('current product verification='+('verified' if selector['b1_arg'] else 'not-requested'),result['result']['message'])
            self.assertEqual(1,len(result['injected']));injection=result['injected'][0];row=result['rows'][injection['index']]
            self.assertEqual('product',row['alias']);self.assertEqual(selector,row['d3']);self.assertEqual(fault,row['result'])
            expected_rows=P2_D3_MODELS[P2_A2_STATE_MODELS[label]]
            endpoint=next(i for i,r in enumerate(expected_rows) if r==selector)
            self.assertEqual(expected_rows[:endpoint+1],[r['d3'] for r in result['rows'] if r['d3'] is not None])
            self.assertEqual([],result['rows'][injection['index']+1:]);self.assertEqual([],result['synthetic_changes'])
            self.assertTrue(all(r['result']=='pass' for r in result['rows'][:injection['index']]))
            self.assertEqual(json.loads(json.dumps(prepared)),result['before'])
            after=snapshot(target);self.assertEqual(injection['snapshot'],result['after']);self.assertEqual(json.loads(json.dumps(after)),result['after'])
            self.p2_assert_sync_prefix(target,after,prepared,candidate,files,b1)
            if selector['phase']=='admission':self.assertEqual(prepared,after)
            has_receipt='.hrn/product/receipts/entry-transition.json' in after
            recovery=self.d3_run(target,preview,recover=has_receipt)
            self.assertEqual(10 if changed else 0,recovery['exit']);self.assertEqual('degraded' if changed else 'replayed' if selector['b1_arg'] else 'updated',recovery['result']['classification'])
            self.assertEqual([],recovery['injected']);self.assertEqual([],recovery['synthetic_changes']);self.assertTrue(all(r['result']=='pass' for r in recovery['rows']))
            self.assertEqual(result['after'],recovery['before'])
            if selector['b1_arg']:
                self.assertEqual(after,snapshot(target))
            else:
                expected=self.p2_complete_snapshot(base,files,candidate,b1)
                if label in {'S3-fallback-staging','S3-fallback-home'}:del expected['.hrn/staging/switch-entry-transition']
                if label=='S3-fallback-home':del expected['.hrn/staging/init-fixture-init']
                self.assertEqual(expected,snapshot(target))
            verified=self.product().verify_workspace_product(target);self.assertEqual('entry-transition',verified['binding_ref']['id'])
            self.assertEqual(sha(b1),verified['binding_ref']['sha256']);self.assertEqual(recovery['after'],json.loads(json.dumps(snapshot(target))))
            if changed:self.assertEqual('unavailable',recovery['result']['transition_content_verification']['classification'])

