        def p2_native_entry_unavailable(self,entry,expected_errno):
            # Direct exec checks actual filesystem availability. runpy is not an exec fence.
            try:
                child=subprocess.Popen([str(entry)],cwd=entry.parent,stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
            except OSError as exc:self.assertEqual(expected_errno,exc.errno)
            else:
                self.children.append(child);self.fail('unavailable native entry unexpectedly started')

        def p2_record_request(self,target,generation,route):
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B','-c',P2_RECORD_FIXTURE_PROGRAM,
                paths['controls'],ctx['invocation_path'],ctx['invocation_sha256'],target,generation,route,'fence'),'record-request')
            _,data=self.finish(child,log,timeout=150);value=json.loads(data)
            self.assertEqual(('verified-api-record-request',generation,route),(value['kind'],value['generation'],value['route']))
            self.assertEqual((child.pid,os.getpgrp()),(value['pid'],value['pgid']))
            self.assertEqual('checkout-1' if generation=='old' else 'entry-1',value['runtime']['inventory_id'])
            return value['argv'],value['request']

        def p2_b_advance(self,target,label,preview=None):
            preview=preview or self.transition(target);initial=snapshot(target)
            candidate,files,b1=self.p2_materials(target,preview,strict=False)
            points={'S1':'after-receipt','S2-full':'after-staged-payload','S3':'after-release','S5':'after-launcher','S6-retained':'after-binding'}
            if label in points:self.interrupted_api(target,preview,points[label])
            elif label in {'S3a','S3b','S4'}:
                self.interrupted_api(target,preview,'after-release')
                event,path,length=('open-after','colvia',None) if label=='S3a' else ('write-after','colvia',None) if label=='S3b' else ('unlink-before','hv2',None)
                code,data,events=self.call(target,self.apply_args(target,preview,recover=True),preview['request'],fault={'event':event,'path':path,'occurrence':1,'write_bytes':length})
                self.assertEqual(-signal.SIGKILL,code,data);last=self.event_rows(events)[-1];self.assertEqual((event,path),(last['event'],last['path']))
            else:self.assertEqual('S0',label)
            self.assertEqual(self.p2_state_snapshot(initial,files,candidate,b1,label),snapshot(target))
            return preview

        def p2_b_runtime_boundary(self,target,executor,state,args,value=None,*,reader=False):
            # Native dispatch is attempted only for a complete declared executor.
            # Missing/truncated executors close availability, never writer-fence coverage.
            before=snapshot(target)
            if executor=='installed-old' and state in {'S5','S6-retained'}:
                self.assertNotIn('hv2',before);self.p2_native_entry_unavailable(target/'hv2',2);return 'entry-absent'
            if executor=='installed-new' and state in {'S0','S1','S2-full','S3','S3a','S3b'}:
                if state not in {'S3a','S3b'}:
                    self.assertNotIn('colvia',before);self.p2_native_entry_unavailable(target/'colvia',2)
                else:
                    raw=(candidate_source/'colvia').read_bytes();size=0 if state=='S3a' else len(raw);raw=raw[:size]
                    self.assertEqual(('file',0o600,size,sha(raw)),before['colvia']);self.p2_native_entry_unavailable(target/'colvia',13)
                return 'entry-incomplete'
            code,data,events=self.call(target,args,value,entry=executor)
            result=json.loads(data)
            if executor=='installed-new' and state in {'S4','S5'}:
                self.assertEqual(65,code,data);self.assertEqual('HV2-WORKSPACE-LAUNCHER',result['code']);self.assertEqual('invalid or unavailable binding/payload; a pending transition may require recovery from independent trusted source',result['message'])
                self.assertFalse(any(r['event']=='lock-attempt' for r in self.event_rows(events)));closure='launcher-window-mismatch'
            elif executor in {'installed-old','old-source'} and state!='S0':
                self.assertEqual(10 if reader else 65,code,data)
                self.assertEqual('HV2-WORKSPACE-PRODUCT',result['error_code' if reader else 'code'])
                self.assertEqual('invalid receipt identity/schema',result['message']);closure='old-schema-refusal'
            elif executor=='new-source' and reader and state not in {'S0','S6-retained'}:
                self.assertEqual(14,code,data);self.assertEqual('partial',result['classification']);self.assertEqual('entry-transition',result['pending_lifecycle']);closure='pending-read'
            else:
                self.assertTrue(reader,'successful writers use positive assertions separately')
                self.assertEqual(0,code,data);self.assertEqual('pass',result['classification']);closure='current-read'
            self.assertEqual(before,snapshot(target));return closure

        def p2_b_record_positive(self,generation,route,name):
            target=self.old_target(name)
            if generation=='new':self.p2_b_advance(target,'S6-retained')
            args,value=self.p2_record_request(target,generation,route);before=snapshot(target)
            code,data,events=self.call(target,args,value,entry='installed-'+generation)
            self.assertEqual(0,code,data);result=json.loads(data);after=snapshot(target)
            if route.endswith('.prepare'):
                self.assertEqual(before,after);self.assertEqual(sha(canonical(result['ticket']))[:16],result['confirm_token'])
            else:
                self.assertNotEqual(before,after)
                rows=self.event_rows(events);self.assertTrue({'lock-attempt','lock-acquired'}<={r['event'] for r in rows})
                for name,row in before.items():
                    if name.startswith('.hrn/product/') or name in {'hv2','colvia','a','.hrn/format.json','.hrn/.gitignore'}:self.assertEqual(row,after[name],name)
                if route=='intent.draft':self.assertEqual(value,result['drafts'][value['revision_id']])
                elif route.startswith('candidate.'):
                    self.assertEqual('saved',result['classification']);self.assertEqual(value,result['store']['decisions'][-1]['request'])
                    if generation=='new':self.assert_candidate_publication_read_witness(rows)
                elif route.startswith('work.publish.'):
                    self.assertEqual(value['revision'],result['revisions'][value['revision']['record_id']]);self.assertEqual(value['identity'],result['identity'])
                elif route=='intent.apply':self.assertIsNotNone(result['current'])
                else:
                    self.assertTrue(route.startswith('work.apply.'));self.assertIsNotNone(result['current']);self.assertFalse(result['pending_decisions']);self.assertFalse(result['pending_selections'])
            return args,value

        def p2_b1_record(self,spec):
            generation,route,state=spec['generation'],spec['route'],spec['state'];executor=spec['executor']
            positive_args,positive_value=self.p2_b_record_positive(generation,route,'positive')
            if (generation,state) in {('old','S0'),('new','S6-retained')}:return
            target=self.old_target('prefix')
            if generation=='old':args,value=self.p2_record_request(target,'old',route)
            else:args,value=positive_args,positive_value
            self.p2_b_advance(target,state)
            # NEW requests are only used at an unavailable/mismatched launcher;
            # they are not represented as an admissible OLD-window writer.
            result=self.p2_b_runtime_boundary(target,executor,state,args,value)
            self.assertIn(result,{'entry-absent','entry-incomplete','launcher-window-mismatch','old-schema-refusal'})

        def p2_b1_source_grammar(self,spec):
            target=self.old_target();before=snapshot(target);route=spec['route'];family=route.split('.')[0]
            action=route.split('.')[1] if family in {'intent','candidate'} else 'publish' if route.startswith('work.publish.') else 'apply'
            args=['--source-checkout',family,action,'--target',target]
            code,data,events=self.call(target,args,{},entry=spec['executor'])
            self.assertEqual(2,code,data);self.assertIn(b'invalid choice',data);self.assertEqual(before,snapshot(target))
            self.assertFalse(any(r['event'].startswith('lock-') for r in self.event_rows(events)))

        def p2_b1_reader(self,spec):
            target=self.old_target();self.p2_b_advance(target,spec['state'])
            args=['status'] if spec['executor'].startswith('installed') else ['--source-checkout','status','--target',target]
            self.p2_b_runtime_boundary(target,spec['executor'],spec['state'],args,reader=True)

        def p2_b_late_fault(self,state):
            last='payload/src/hv2ref/workspace.py'
            event,path,length={
                'S1':('buffered-close-after','.hrn/product/receipts/entry-transition.json',None),
                'S2-full':('buffered-close-after','.hrn/staging/switch-entry-transition/'+P2_RELEASE_ID+'/'+last,None),
                'S3':('rename-after','.hrn/product/releases/'+P2_RELEASE_ID,None),
                'S3a':('open-after','colvia',None),'S3b':('write-after','colvia',None),
                'S4':('unlink-before','hv2',None),'S5':('unlink-after','hv2',None),
                'S6-retained':('replace-after','.hrn/product/binding.json',None)}[state]
            return {'event':event,'path':path,'occurrence':1,'write_bytes':length}

        def p2_b_late_run(self,target,preview,args,value,executor,state):
            initial=snapshot(target);candidate,files,b1=self.p2_materials(target,preview,strict=False)
            fault=self.p2_b_late_fault(state)
            new_child,new_log,new_events,ready,release,_=self.call(target,self.apply_args(target,preview),preview['request'],fault=fault,pause=True)
            token=self.wait_ready(new_child,ready,target)
            command,events,_,_,_=self.scenario(target,entry=executor,argv=args,pause=False)
            old_child,old_log=self.spawn(command,'late-old',value)
            deadline=time.monotonic()+self.remaining(60)
            while not events.exists() or not any(r['event']=='lock-attempt' for r in self.event_rows(events)):
                self.assertIsNone(old_child.poll(),'OLD exited before actual lock attempt');self.assertLess(time.monotonic(),deadline);time.sleep(0.02)
            self.assertFalse(any(r['event']=='lock-acquired' for r in self.event_rows(events)))
            self.assertEqual(initial,snapshot(target),'paused NEW has not published the transition')
            self.release_pause(release,token);self.finish(new_child,new_log,timeout=150,expected=-signal.SIGKILL)
            _,data=self.finish(old_child,old_log,timeout=150,expected=65);error=json.loads(data)
            self.assertEqual(('HV2-WORKSPACE-PRODUCT','invalid receipt identity/schema'),(error['code'],error['message']))
            self.assertEqual(self.p2_state_snapshot(initial,files,candidate,b1,state),snapshot(target),'waiting OLD writer published no bytes')
            old_rows=self.event_rows(events);new_rows=self.event_rows(new_events)
            self.assertEqual((fault['event'],fault['path']),(new_rows[-1]['event'],new_rows[-1]['path']))
            attempt=next(r for r in old_rows if r['event']=='lock-attempt');acquired=next(r for r in old_rows if r['event']=='lock-acquired')
            self.assertEqual(old_child.pid,attempt['pid']);self.assertEqual(attempt['detail'],acquired['detail'])
            self.assertEqual((token['lock']['dev'],token['lock']['ino']),(attempt['detail']['dev'],attempt['detail']['ino']))
            self.assertLess(attempt['seq'],acquired['seq']);self.assertGreaterEqual(acquired['monotonic_ns'],new_rows[-1]['monotonic_ns']);self.assert_lock_free(target)

        def p2_b2_record(self,spec):
            self.p2_b_record_positive('old',spec['route'],'positive')
            target=self.old_target('prefix');args,value=self.p2_record_request(target,'old',spec['route'])
            preview=self.transition(target);self.p2_b_late_run(target,preview,args,value,spec['executor'],spec['state'])

        def p2_lifecycle_prefix(self,target,executor,route):
            args=[] if executor.startswith('installed') else ['--source-checkout']
            args += [route]
            if not executor.startswith('installed'):
                args += ['--target',str(target)]
                if route!='repair':args += ['--profile','checkout-1' if executor=='old-source' else 'entry-1']
            return args

        def p2_lifecycle_request(self,target,executor,route,source=None):
            prefix=self.p2_lifecycle_prefix(target,executor,route)
            args=prefix+['--operation-id','fence-'+route,'--observed-at',FIXTURE_TIME]
            if route in {'init','update','repair'}:args += ['--source',str(source)]
            if route=='init':args += ['--authority-home-id','fixture-home']
            if route=='repair':args += ['--backup',str(self.base/(target.name+'-repair-backup'))]
            before=snapshot(target);code,data,events=self.call(target,args,entry=executor)
            self.assertEqual(0,code,data);preview=json.loads(data);self.assertEqual('preview',preview['classification']);self.assertEqual(before,snapshot(target))
            apply=prefix+['--apply','--input','-','--confirm',preview['confirm_token']]
            if route in {'init','update','repair'}:apply += ['--source',str(source)]
            return apply,preview['request']

        def p2_lifecycle_fixture(self,name,generation,route,executor):
            counterpart=None;history=None;source=old_source if generation=='old' else candidate_source
            if route=='init':target=self.directory(name)
            elif generation=='old' and route in {'update','rollback'}:
                target,counterpart,history=self.old_history_target(name)
                self.verify_counterpart(counterpart,history)
                if route=='update':source=counterpart
            else:
                target=self.old_target(name)
                if generation=='new':self.p2_b_advance(target,'S6-retained')
                if generation=='new' and route in {'update','rollback'}:
                    other=self.directory(name+'-new-counterpart')
                    for member,data in self.product().workspace_candidate(candidate_source)['payload'].items():write_file(other/member,data,0o755 if member=='colvia' else 0o644)
                    with (other/'README.md').open('ab') as handle:handle.write(b'\nSynthetic P2 same-window lifecycle counterpart.\n')
                    if route=='update':source=other
                    else:
                        first=self.product().workspace_switch_preview(target,action='update',source=other,operation_id='fence-new-history',created_at=FIXTURE_TIME)
                        self.product().workspace_switch_apply(target,first['request'],confirm_token=first['confirm_token'],source=other)
            if route=='repair':
                launcher='hv2' if generation=='old' else 'colvia'
                (target/launcher).write_bytes(b'synthetic managed launcher damage\n')
            args,value=self.p2_lifecycle_request(target,executor,route,source)
            return target,args,value,counterpart,history

        def p2_lifecycle_positive(self,generation,route,executor,name='positive'):
            target,args,value,counterpart,history=self.p2_lifecycle_fixture(name,generation,route,executor)
            before=snapshot(target);project=before.get('a');code,data,events=self.call(target,args,value,entry=executor)
            self.assertEqual(0,code,data);result=json.loads(data)
            self.assertEqual({'init':'initialized','update':'updated','rollback':'rolled-back','repair':'repaired','detach':'detached'}[route],result['classification'])
            self.assertNotEqual(before,snapshot(target))
            if project is not None:self.assertEqual(project,snapshot(target)['a'])
            rows=self.event_rows(events);self.assertTrue({'lock-attempt','lock-acquired'}<={r['event'] for r in rows})
            if generation=='old' and route in {'update','rollback'}:
                # Ends at X: inspect binding/state only, never execute X as audited OLD.
                self.verify_counterpart(counterpart,history)
                self.assertEqual(history['counterpart'],json.loads((target/'.hrn/product/binding.json').read_bytes())['active_release'])
                self.assertEqual((old_source/'hv2').read_bytes(),(target/'hv2').read_bytes())
            elif route in {'update','rollback'}:
                self.assertEqual(value['candidate_release'],self.product()._workspace_observe(target)['binding']['active_release'])
            elif generation=='new' and route=='repair':self.assertEqual((candidate_source/'colvia').read_bytes(),(target/'colvia').read_bytes())
            elif route=='detach':
                self.assertFalse((target/('hv2' if generation=='old' else 'colvia')).exists());self.assertTrue((target/'.hrn/detached.json').is_file())
            return target

        def p2_b_source_precondition(self,target,generation,route,state):
            executor=generation+'-source';args=self.p2_lifecycle_prefix(target,executor,route)
            args += ['--operation-id','fence-precondition','--observed-at',FIXTURE_TIME]
            if route in {'init','repair'}:args += ['--source',str(old_source if generation=='old' else candidate_source)]
            if route=='init':args += ['--authority-home-id','fixture-home']
            if route=='repair':args += ['--backup',str(self.base/'unused-backup')]
            before=snapshot(target);code,data,events=self.call(target,args,entry=executor)
            self.assertEqual(65,code,data);error=json.loads(data);self.assertEqual('HV2-WORKSPACE-PRODUCT',error['code'])
            if route=='init':expected='different initialization plan'
            elif generation=='old' and state!='S0':expected='invalid receipt identity/schema'
            elif generation=='new' and state not in {'S0','S6-retained'}:expected='pending lifecycle blocks product use; recover exact plan from independent source'
            elif route=='repair':expected='active release needs no repair' if generation=='old' or state=='S6-retained' else 'older-window repair requires the exact retained old source'
            elif route=='rollback':expected='old-window rollback requires the retained old source' if state=='S0' else 'new source switches only to entry-1; first transition cannot roll back to checkout-1'
            else:self.assertEqual('detach',route);expected='older-window detach requires retained old source'
            self.assertEqual(expected,error['message']);self.assertEqual(before,snapshot(target))
            self.assertFalse(any(r['event']=='lock-attempt' for r in self.event_rows(events)))
            if route=='repair':self.assertFalse((self.base/'unused-backup').exists())

        def p2_b1_lifecycle(self,spec):
            gen,route,executor,state=(spec[k] for k in ('generation','route','executor','state'))
            self.p2_lifecycle_positive(gen,route,executor)
            if gen=='old' and route not in {'init','repair'}:
                if state=='S0':return
                target,args,value,counterpart,history=self.p2_lifecycle_fixture('prefix','old',route,executor)
                if counterpart is not None:self.verify_counterpart(counterpart,history)
                self.p2_b_advance(target,state)
                self.p2_b_runtime_boundary(target,executor,state,args,value);return
            target=self.old_target('prefix')
            if gen=='new' and executor=='new-source' and route=='update':
                args,value=self.p2_lifecycle_request(target,executor,route,candidate_source)
                self.p2_b_advance(target,state)
                before=snapshot(target);code,data,events=self.call(target,args,value,entry=executor);result=json.loads(data)
                if state=='S0':self.assertEqual(0,code,data);self.assertEqual('updated',result['classification'])
                else:
                    self.assertEqual(65,code,data);self.assertEqual('HV2-WORKSPACE-PRODUCT',result['code'])
                    self.assertEqual('binding changed since preview' if state=='S6-retained' else 'pending lifecycle requires same explicit recovery',result['message']);self.assertEqual(before,snapshot(target))
                return
            self.p2_b_advance(target,state)
            if executor.startswith('installed'):
                if state=='S6-retained':
                    if route=='rollback':
                        before=snapshot(target);args=[route,'--operation-id','fence-current','--observed-at',FIXTURE_TIME]
                        code,data,_=self.call(target,args,entry=executor);self.assertEqual(65,code,data)
                        self.assertEqual('new source switches only to entry-1; first transition cannot roll back to checkout-1',json.loads(data)['message']);self.assertEqual(before,snapshot(target))
                    else:
                        source=candidate_source
                        if route=='update':
                            source=self.directory('prefix-new-counterpart')
                            for member,data in self.product().workspace_candidate(candidate_source)['payload'].items():
                                write_file(source/member,data,0o755 if member=='colvia' else 0o644)
                            with (source/'README.md').open('ab') as handle:
                                handle.write(b'\nSynthetic P2 same-window lifecycle counterpart.\n')
                        args,value=self.p2_lifecycle_request(target,executor,route,source)
                        code,data,_=self.call(target,args,value,entry=executor);self.assertEqual(0,code,data)
                        self.assertEqual('updated' if route=='update' else 'detached',json.loads(data)['classification'])
                else:self.p2_b_runtime_boundary(target,executor,state,[route,'--operation-id','fence-unavailable','--observed-at',FIXTURE_TIME])
            elif gen=='new' and route=='detach' and state=='S6-retained':
                args,value=self.p2_lifecycle_request(target,executor,route)
                code,data,_=self.call(target,args,value,entry=executor);self.assertEqual(0,code,data);self.assertEqual('detached',json.loads(data)['classification'])
            else:self.p2_b_source_precondition(target,gen,route,state)

        def p2_b2_lifecycle(self,spec):
            route,executor,state=(spec[k] for k in ('route','executor','state'))
            self.p2_lifecycle_positive('old',route,executor)
            if route in {'init','repair'}:
                # No healthy audited P target simultaneously satisfies OLD init's
                # empty root or OLD repair's damaged-member prerequisite. These
                # fixed rows prove that boundary; no lock recheck is claimed.
                target=self.old_target('prefix');self.p2_b_advance(target,state)
                self.p2_b_source_precondition(target,'old',route,state);return
            target,args,value,counterpart,history=self.p2_lifecycle_fixture('prefix','old',route,executor)
            if counterpart is not None:self.verify_counterpart(counterpart,history)
            preview=self.transition(target);self.p2_b_late_run(target,preview,args,value,executor,state)

        def p2_b1_stale_ticket(self,spec):
            route=spec['route'];self.p2_b_record_positive('old',route,'positive')
            target=self.old_target('prefix');args,value=self.p2_record_request(target,'old',route)
            request_bytes=canonical(value);old_binding=copy.deepcopy(value['product_binding_ref'])
            preview=self.p2_b_advance(target,'S6-retained')
            if spec['replay']:
                code,data,_=self.call(target,self.apply_args(target,preview,recover=True),preview['request'])
                self.assertEqual(0,code,data);self.assertEqual('replayed',json.loads(data)['classification'])
            before=snapshot(target);code,data,events=self.call(target,args,value,entry='installed-new')
            self.assertEqual(65,code,data);error=json.loads(data)
            self.assertEqual('HV2-WORK-RECORD',error['code']);self.assertEqual('active binding changed',error['message'])
            self.assertEqual(before,snapshot(target));self.assertEqual(request_bytes,canonical(value))
            self.assertNotEqual(old_binding,self.product().verify_workspace_product(target)['binding_ref'])
            self.assertTrue({'lock-attempt','lock-acquired'}<={r['event'] for r in self.event_rows(events)})

        def p2_fixture_git(self,target,*args):
            child,log=self.spawn((config['git']['path'],'-C',target,*args),'synthetic-git')
            _,data=self.finish(child,log,timeout=15)
            return data

        def p2_old_lifecycle_api(self,target,source,request,point,mode):
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B','-c',P2_C1_OLD_LIFECYCLE_PROGRAM,
                paths['controls'],ctx['invocation_path'],ctx['invocation_sha256'],target,source,point,mode),'old-lifecycle-api',request)
            _,data=self.finish(child,log,timeout=150);result=json.loads(data)
            self.assertEqual(('fixed-old-lifecycle-api',point,mode),(result['kind'],result['point'],result['mode']))
            self.assertEqual((child.pid,os.getpgrp()),(result['pid'],result['pgid']))
            return result

        def p2_gap_old_prefix(self,target,point):
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B','-c',P2_GAP_C1_OLD_PREFIX_PROGRAM,
                old_source,target,point),'gap-old-prefix')
            _,data=self.finish(child,log,timeout=150);result=json.loads(data)
            self.assertEqual(('gap-actual-old-prefix',point),(result['kind'],result['point']))
            self.assertEqual((child.pid,os.getpgrp()),(result['pid'],result['pgid']))
            self.assertEqual('checkout-1',result['release_ref']['inventory_id'])
            self.assertEqual(result['after'],json.loads(canonical(snapshot(target))))
            return result

        def p2_gap_preview_args(self,target,operation,backup):
            # Repair has no --profile option in the actual source CLI.
            args=['--source-checkout',operation,'--target',target]
            if operation!='repair':args+=['--profile','entry-1']
            if operation in {'init','update','repair'}:args+=['--source',candidate_source]
            if operation=='init':args+=['--authority-home-id','fixture-home']
            if operation=='repair':args+=['--backup',backup]
            args+=['--operation-id','entry-transition' if operation=='update' else 'gap-new-'+operation,
                '--observed-at',FIXTURE_TIME]
            return args

        def p2_gap_read_events(self,events):
            rows=self.event_rows(events);opens=[]
            for row in rows:
                event=row['event'];detail=row['detail']
                self.assertIn(event,{'audit-before:open','open-before','open-after'},rows)
                self.assertIs(type(row['path']),str)
                if event=='audit-before:open':
                    self.assertIs(type(detail),str)
                    parsed=ast.literal_eval(detail)
                    self.assertIs(type(parsed),tuple);self.assertEqual(2,len(parsed))
                    mode,flags=parsed;self.assertIn(mode,(None,'r'))
                else:
                    self.assertIs(type(detail),dict)
                    self.assertIn(set(detail),({'flags','mode'},{'flags','mode','dir_fd'}))
                    flags=detail['flags'];self.assertIs(type(detail['mode']),int)
                    if 'dir_fd' in detail:
                        self.assertIs(type(detail['dir_fd']),int);self.assertGreaterEqual(detail['dir_fd'],0)
                    if event=='open-before':opens.append((row['path'],detail))
                    else:
                        self.assertTrue(opens,rows)
                        self.assertEqual(opens.pop(),(row['path'],detail),rows)
                self.assertIs(type(flags),int)
                self.assertEqual(os.O_RDONLY,flags & os.O_ACCMODE)
                self.assertEqual(0,flags & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND))
            self.assertEqual([],opens,rows)

        def p2_gap_read_call(self,target,classification,exit_code,*,command='status',required=(),forbidden=(),request=None):
            before=snapshot(target);request_bytes=canonical(request)
            backup=self.base/'diagnostic-backup';self.assertFalse(backup.exists())
            code,data,events=self.call(target,['--source-checkout',command,'--target',target])
            self.assertEqual(exit_code,code,data)
            if command=='view':
                result=data.decode('utf-8');self.assertIn('next\\_action',result)
                self.assertIn(classification,result);message=result
            else:
                result=json.loads(data);self.assertEqual(classification,result['classification'])
                message=result.get('next_action','')
                if classification!='pass':self.assertNotEqual('pass',result['classification'])
            for value in required:self.assertIn(value,message)
            for value in forbidden:self.assertNotIn(value,message)
            self.p2_gap_read_events(events)
            self.assertEqual(before,snapshot(target));self.assertEqual(request_bytes,canonical(request))
            self.assertFalse(backup.exists())
            with (self.base/'gap-read-cases.jsonl').open('a',encoding='utf-8') as out:
                out.write(json.dumps({'target':target.name,'command':command,'exit':code,'result':result,
                    'events':str(events),'snapshot_unchanged':True,'request_unchanged':True,'backup_absent':True},sort_keys=True)+'\n')
            return result

        def p2_gap_observed_call(self,target,args,expected,*,prefix,operation,invocation,backup,value=None):
            before=snapshot(target);request_bytes=canonical(value)
            self.assertFalse(backup.exists())
            self.assertFalse((target/'.hrn/product/receipts/entry-transition.json').exists())
            code,data,events=self.call(target,args,value)
            result=json.loads(data)
            if expected is None:
                self.assertEqual(14,code,data);self.assertEqual('partial',result['classification'])
                self.assertNotEqual('verified',result.get('product_verification'))
            else:
                self.assertEqual(65,code,data)
                self.assertEqual(('HV2-WORKSPACE-PRODUCT',expected),(result['code'],result['message']))
            self.assertEqual(before,snapshot(target));self.assertEqual(request_bytes,canonical(value))
            self.assertFalse(backup.exists())
            self.assertFalse((target/'.hrn/product/receipts/entry-transition.json').exists())
            # Only read opens are allowed. Mutation attempts are failures even if
            # bytes happen to be unchanged; observer diagnostics are not PASS.
            self.p2_gap_read_events(events)
            if expected is None:
                self.assertIn('exact original init request',result['next_action'])
                self.assertIn('for an OLD pending init, use the retained matching OLD source',result['next_action'])
                self.assertIn('manual preservation',result['next_action'])
            with (self.base/'gap-cases.jsonl').open('a',encoding='utf-8') as out:
                out.write(json.dumps({'prefix':prefix,'operation':operation,'invocation':invocation,
                    'exit':code,'result':result,'events':str(events),'snapshot_unchanged':True,
                    'request_unchanged':True,'transition_receipt_absent':True,'backup_absent':True},sort_keys=True)+'\n')

        def p2_gap_init_case(self,operation):
            for point in ('after-plan','after-launcher'):
                with self.subTest(prefix=point,operation=operation):
                    target=self.directory(point);backup=self.base/('backup-'+point)
                    saved=None
                    if operation=='init':
                        before=snapshot(target)
                        saved=self.product().workspace_init_preview(candidate_source,target,
                            authority_home_id='fixture-home',operation_id='gap-new-init',created_at=FIXTURE_TIME)
                        self.assertEqual(before,snapshot(target))
                    old=self.p2_gap_old_prefix(target,point)
                    expected='different initialization plan' if operation=='init' else (
                        'root is not ready' if point=='after-plan' else 'product unavailable, malformed or unstable')
                    self.p2_gap_observed_call(target,self.p2_gap_preview_args(target,operation,backup),expected,
                        prefix=point,operation=operation,invocation='preview',backup=backup)
                    if operation=='init':
                        for recover in (False,True):
                            args=['--source-checkout','init','--profile','entry-1','--target',target,'--source',candidate_source,
                                '--apply','--input','-','--confirm',saved['confirm_token'],*(['--recover'] if recover else [])]
                            self.p2_gap_observed_call(target,args,expected,prefix=point,operation=operation,
                                invocation='new-request-recover' if recover else 'new-request-apply',backup=backup,value=saved['request'])
                        args=['--source-checkout','init','--profile','entry-1','--target',target,'--source',candidate_source,
                            '--apply','--input','-','--confirm',old['preview']['confirm_token'],'--recover']
                        self.p2_gap_observed_call(target,args,'source changed since init preview',prefix=point,
                            operation=operation,invocation='old-exact-request-source-fence',backup=backup,value=old['preview']['request'])
                        self.p2_gap_observed_call(target,['--source-checkout','status','--target',target],None,
                            prefix=point,operation='status',invocation='read',backup=backup)
                        if point=='after-plan':
                            for command in ('doctor','view'):
                                self.p2_gap_read_call(target,'partial',14,command=command,request=old['preview']['request'],
                                    required=('exact original init request','for an OLD pending init, use the retained matching OLD source','manual preservation'))

        def p2_gap_detach_case(self,operation):
            target=self.old_target();backup=self.base/'backup';saved=None
            if operation=='update':
                before=snapshot(target);saved=self.transition(target);self.assertEqual(before,snapshot(target))
            self.p2_gap_old_prefix(target,'after-receipt')
            expected='different initialization plan' if operation=='init' else 'root is not ready'
            self.p2_gap_observed_call(target,self.p2_gap_preview_args(target,operation,backup),expected,
                prefix='after-receipt',operation=operation,invocation='preview',backup=backup)
            if operation=='update':
                for recover in (False,True):
                    self.p2_gap_observed_call(target,self.apply_args(target,saved,recover=recover),expected,
                        prefix='after-receipt',operation=operation,invocation='recover' if recover else 'apply',
                        backup=backup,value=saved['request'])

