        def test_p2_gap_read_new_pending_source(self):
            from hv2ref.errors import InjectedCrash
            product=self.product()
            for point in ('after-plan','after-launcher'):
                with self.subTest(kind='new-init',point=point):
                    target=self.directory('new-init-'+point)
                    preview=product.workspace_init_preview(candidate_source,target,authority_home_id='fixture-home',operation_id='gap-new-init',created_at=FIXTURE_TIME)
                    with self.assertRaises(InjectedCrash) as caught:
                        product.workspace_init_apply(candidate_source,target,preview['request'],confirm_token=preview['confirm_token'],inject_at=point)
                    self.assertEqual(point,caught.exception.point)
                    result=self.p2_gap_read_call(target,'partial',14,request=preview['request'],
                        required=('matching the candidate release','exact original init request','for an OLD pending init, use the retained matching OLD source','manual preservation'))
                    self.assertNotIn('pending_lifecycle',result)
            target=self.old_target('new-transition');preview=self.transition(target)
            self.interrupted_api(target,preview,'after-receipt')
            self.assertEqual('entry-1',preview['request']['candidate_release']['inventory_id'])
            result=self.p2_gap_read_call(target,'partial',14,request=preview['request'],
                required=('recover exact lifecycle request from independent trusted source','receipt alone is not completion'),forbidden=('matching OLD source',))
            self.assertEqual('entry-transition',result['pending_lifecycle'])
            target=self.directory('new-same-entry');self.new_init(target);other=self.d3_other_source()
            preview=product.workspace_switch_preview(target,action='update',source=other,operation_id='gap-same-entry',created_at=FIXTURE_TIME)
            with self.assertRaises(InjectedCrash) as caught:
                product.workspace_switch_apply(target,preview['request'],confirm_token=preview['confirm_token'],source=other,inject_at='after-receipt')
            self.assertEqual('after-receipt',caught.exception.point)
            result=self.p2_gap_read_call(target,'partial',14,request=preview['request'],
                required=('recover exact lifecycle request from independent trusted source',),forbidden=('matching OLD source',))
            self.assertEqual('gap-same-entry',result['pending_lifecycle'])
            target=self.directory('new-detach');self.new_init(target)
            preview=product.workspace_detach_preview(target,operation_id='gap-new-detach',created_at=FIXTURE_TIME)
            with self.assertRaises(InjectedCrash) as caught:
                product.workspace_detach_apply(target,preview['request'],confirm_token=preview['confirm_token'],inject_at='after-receipt')
            self.assertEqual('after-receipt',caught.exception.point)
            result=self.p2_gap_read_call(target,'partial',14,request=preview['request'],forbidden=('matching OLD source','init'))
            self.assertEqual(3,result['receipt']['plan']['schema_version'])
            self.assertEqual('preserve remaining files; use the exact original detach request and confirmation token with --recover from an independent trusted source',result['next_action'])

        def test_p2_gap_read_nonpending_and_unknown(self):
            from hv2ref.errors import InjectedCrash
            product=self.product();target=self.directory('fresh')
            result=self.p2_gap_read_call(target,'uninitialized',15)
            self.assertNotIn('next_action',result)
            target=self.directory('healthy');self.new_init(target)
            result=self.p2_gap_read_call(target,'pass',0,required=('read ', '/docs/README.md'),forbidden=('matching OLD source','recover'))
            self.assertEqual('entry-1',result['product']['inventory']['inventory_id'])
            target=self.directory('completed-detach');self.new_init(target)
            preview=product.workspace_detach_preview(target,operation_id='gap-complete-detach',created_at=FIXTURE_TIME)
            product.workspace_detach_apply(target,preview['request'],confirm_token=preview['confirm_token'])
            result=self.p2_gap_read_call(target,'detached',0,request=preview['request'])
            self.assertEqual('read retained project truth with an independent trusted source; no active product runtime remains',result['next_action'])
            self.assertEqual([],result['remaining_files']);self.assertEqual([],result['remaining_directories'])
            target=self.directory('malformed-init')
            preview=product.workspace_init_preview(candidate_source,target,authority_home_id='fixture-home',operation_id='gap-malformed-init',created_at=FIXTURE_TIME)
            with self.assertRaises(InjectedCrash) as caught:
                product.workspace_init_apply(candidate_source,target,preview['request'],confirm_token=preview['confirm_token'],inject_at='after-plan')
            self.assertEqual('after-plan',caught.exception.point)
            (target/'.hrn/product/init-plan.json').write_bytes(b'{"malformed":true}\n')
            result=self.p2_gap_read_call(target,'degraded',10,request=preview['request'])
            self.assertEqual('unrecognized',result['root_classification'])
            self.assertNotIn('next_action',result);self.assertIn('preserve bytes',result['recovery'])

        def p2_c1_pending_record(self,target,spec):
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B','-c',P2_C1_RECORD_PENDING_PROGRAM,
                paths['controls'],ctx['invocation_path'],ctx['invocation_sha256'],target,'old',spec['route'],'fence',spec['point'],spec['state']),'old-pending-record')
            _,data=self.finish(child,log,timeout=150);result=json.loads(data)
            self.assertEqual(('old-persisted-record',spec['route'],spec['point'],spec['state']),
                (result['kind'],result['route'],result['point'],result['state']))
            self.assertEqual((child.pid,os.getpgrp()),(result['pid'],result['pgid']))
            self.assertEqual(spec['state']=='pending',any(result['pending'].values()))
            self.assertEqual('checkout-1',result['runtime']['inventory_id'])

        def p2_c1_attempt(self,target,preview,invocation,expected=None):
            from hv2ref.errors import ContractError
            before=snapshot(target)
            if invocation=='preview':
                if expected is None:
                    current=self.transition(target);self.assertEqual(preview,current);result=current
                else:
                    with self.assertRaises(ContractError) as caught:self.transition(target)
                    self.assertEqual(expected,(caught.exception.code,caught.exception.message));result=None
            else:
                code,data,events=self.call(target,self.apply_args(target,preview,recover=invocation=='recover-new-request'),preview['request'])
                result=json.loads(data)
                self.assertEqual(0 if expected is None else 65,code,data)
                if expected is not None:self.assertEqual(expected,(result['code'],result['message']))
                else:
                    self.assertEqual('updated',result['classification'])
                    self.assertEqual('entry-1',self.product().verify_workspace_product(target)['inventory']['inventory_id'])
                    self.assertNotIn('hv2',snapshot(target));self.assertEqual(before['a'],snapshot(target)['a'])
            if expected is not None or invocation=='preview':
                self.assertEqual(before,snapshot(target));self.assertFalse((target/'.hrn/product/receipts/entry-transition.json').exists())
            return result

        def p2_c1_case(self,index):
            spec=P2_C1_ROWS[index];kind=spec['kind'];case=spec.get('case');invocation=spec['invocation']
            product=self.product();expected=None;counterpart=None;history=None
            if kind=='old-pending' or (kind=='predecessor' and case in {'audited-history','other-valid-release'}):
                target,counterpart,history=self.old_history_target('target')
            else:target=self.old_target()
            if kind=='old-pending' and spec['point'] in {'after-staged-inventory','after-staged-payload'}:
                target=self.old_target('pending-target')
                self.assertFalse((target/'.hrn/product/releases'/history['counterpart']['id']).exists())
            if kind in {'index','ignore'}:
                # Fixed OLD init remains a non-Git fixture. The same path is then
                # made a synthetic primary Git root; path fingerprint stays fixed.
                before_product={k:v for k,v in snapshot(target).items() if k.startswith('.hrn/product/') or k=='hv2'}
                self.p2_fixture_git(target,'init','-q')
                from hv2ref.workspace import classify_target,target_fingerprint
                self.assertEqual('primary',classify_target(target)['kind'])
                self.assertEqual(before_product,{k:v for k,v in snapshot(target).items() if k.startswith('.hrn/product/') or k=='hv2'})
                self.assertEqual(json.loads((target/'.hrn/product/init-plan.json').read_bytes())['target_fingerprint'],target_fingerprint(target))
                self.assertEqual('checkout-1',product.verify_workspace_product(target)['inventory']['inventory_id'])
            # Every negative starts with an actually admitted same-target request.
            before=snapshot(target);preview=self.transition(target);self.assertEqual(before,snapshot(target))
            if kind=='predecessor':
                if case=='other-valid-release':
                    _,old_request=self.p2_lifecycle_request(target,'old-source','update',counterpart)
                    self.p2_old_lifecycle_api(target,counterpart,old_request,'after-receipt','interrupt')
                    self.p2_old_lifecycle_api(target,counterpart,old_request,'after-receipt','recover')
                    self.verify_counterpart(counterpart,history)
                    self.assertEqual(history['counterpart'],product._workspace_observe(target)['binding']['active_release'])
                    expected=('HV2-WORKSPACE-PRODUCT','entry transition predecessor is not the audited release' if invocation=='preview' else 'binding changed since preview')
                elif case in {'mode-0700','mode-0644'}:
                    (target/'hv2').chmod(0o700 if case=='mode-0700' else 0o644)
                    expected=('HV2-WORKSPACE-PRODUCT','transition predecessor launcher mode' if case=='mode-0700' else 'launcher differs from permitted release or is not executable')
                elif case=='changed-bytes':
                    (target/'hv2').write_bytes(b'synthetic changed OLD entry\n')
                    expected=('HV2-WORKSPACE-PRODUCT','launcher differs from permitted release or is not executable')
                elif case=='case-alias':
                    (target/'hv2').rename(target/'HV2')
                    names={p.name for p in target.iterdir()};self.assertIn('HV2',names);self.assertNotIn('hv2',names)
                    # This explicit decision uses filesystem identity, never the returned error.
                    expected=('HV2-WORKSPACE-PRODUCT','transition predecessor launcher missing or aliased' if (target/'hv2').exists() else 'product unavailable, malformed or unstable')
                elif case=='symlink':
                    (target/'hv2').unlink();(target/'hv2').symlink_to('.hrn/product/releases/'+product.ENTRY_PREDECESSOR['id']+'/payload/hv2')
                    expected=('HV2-WORKSPACE-CONTRACT','wrong file type: hv2')
                else:self.assertIn(case,{'audited','audited-history'})
            elif kind=='old-pending':
                _,old_request=self.p2_lifecycle_request(target,'old-source','update',counterpart)
                self.p2_old_lifecycle_api(target,counterpart,old_request,spec['point'],'interrupt')
                state=product._workspace_observe(target,allow_pending=True)
                self.assertEqual(old_request,state['pending']['plan']);self.assertEqual(history['predecessor'],state['binding']['active_release'])
                if invocation=='recover-old-source':
                    original=(target/'a').read_bytes();result=self.p2_old_lifecycle_api(target,counterpart,old_request,spec['point'],'recover')
                    self.assertEqual('updated',result['result']['classification'])
                    self.assertEqual(original,(target/'a').read_bytes());self.verify_counterpart(counterpart,history)
                    self.assertFalse((target/'.hrn/product/receipts/entry-transition.json').exists())
                    self.assertEqual(history['counterpart'],product._workspace_observe(target)['binding']['active_release']);return
                expected=('HV2-WORKSPACE-PRODUCT','pending lifecycle blocks product use; recover exact plan from independent source' if invocation=='preview' else 'pending lifecycle requires same explicit recovery')
            elif kind=='root':
                if case in {'file','case-alias'}:write_file(target/('colvia' if case=='file' else 'COLVIA'),b'synthetic project-owned entry\n')
                elif case=='directory':(target/'colvia').mkdir()
                else:self.assertEqual('dangling-link',case);(target/'colvia').symlink_to('absent-synthetic-destination')
                expected=('HV2-WORKSPACE-PRODUCT','preexisting launcher or alias is not owned')
            elif kind=='index':
                path=target/case;write_file(path,b'synthetic indexed member\n');self.p2_fixture_git(target,'add','--',case);path.unlink()
                if '/' in case:path.parent.rmdir()
                self.assertEqual(case.encode()+b'\0',self.p2_fixture_git(target,'ls-files','-z'))
                if case!='unrelated':expected=('HV2-WORKSPACE-PRODUCT','new launcher or alias/descendant is tracked')
            elif kind=='ignore':
                if case=='root-pattern':write_file(target/'.gitignore',b'colvia\n')
                elif case=='info-exclude':
                    with (target/'.git/info/exclude').open('ab') as handle:handle.write(b'\ncolvia\n')
                elif case=='bounded-excludes-file':
                    excludes=self.base/'synthetic-excludes';write_file(excludes,b'colvia\n')
                    self.p2_fixture_git(target,'config','--local','core.excludesFile',str(excludes))
                else:self.assertEqual('negated-pattern',case);write_file(target/'.gitignore',b'colvia\n!colvia\n')
                if case!='negated-pattern':expected=('HV2-WORK-RECORD','truth hidden by effective Git ignore policy')
            else:
                self.assertEqual('persisted-record',kind);self.p2_c1_pending_record(target,spec)
                if spec['point']=='after-staged-current':
                    self.assertEqual('work.publish.start',spec['route'])
                    staged=[p for p in (target/'.hrn/staging').iterdir() if p.name.startswith('work-current-')]
                    self.assertEqual(1,len(staged));stage=staged[0];info=stage.lstat()
                    self.assertTrue(stat.S_ISREG(info.st_mode));self.assertEqual((0o600,1),(stat.S_IMODE(info.st_mode),info.st_nlink))
                    selection_bytes=(target/'.hrn/work/fence-work/selections/fence-selection-1.json').read_bytes()
                    selection=json.loads(selection_bytes);self.assertEqual(selection_bytes,canonical(selection))
                    self.assertEqual('fence-selection-1',selection['record_id'])
                    staged_current={'authority_home_id':'fixture-home','record_type':'work-current','schema_version':1,
                        'work_id':'fence-work','selection_ref':{'id':'fence-selection-1','sha256':sha(selection_bytes)}}
                    self.assertEqual(canonical(staged_current),stage.read_bytes())
                    if invocation=='preview':expected=('HV2-WORKSPACE-CONTRACT','wrong file type: '+stage.name)
                    else:expected=('HV2-WORKSPACE-PRODUCT','pending Work blocks lifecycle' if spec['state']=='pending' else 'truth changed since lifecycle preview')
                elif spec['state']=='pending':expected=('HV2-WORKSPACE-PRODUCT','pending intent blocks lifecycle' if spec['route']=='intent.apply' else 'pending Work blocks lifecycle')
                else:preview=self.transition(target)
            self.p2_c1_attempt(target,preview,invocation,expected)
            if counterpart is not None:self.verify_counterpart(counterpart,history)

        def p2_local_graph(self,target,spec):
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B','-c',P2_C2_FIXTURE_PROGRAM,
                paths['controls'],ctx['invocation_path'],ctx['invocation_sha256'],target),'old-local-graph',spec)
            _,data=self.finish(child,log,timeout=150);result=json.loads(data)
            self.assertEqual('verified-old-graph',result['kind']);self.assertEqual(spec,result['spec'])
            self.assertEqual((child.pid,os.getpgrp()),(result['pid'],result['pgid']))
            self.assertEqual('checkout-1',result['runtime']['inventory_id'])
            if result['outcome']=='constructed':
                wid='c2-parent' if spec['schema']==2 else 'c2-local'
                self.assertEqual('completed' if spec.get('variation') in {'completed-parent','completed-local'} else spec['state'],result['summary'][wid]['state'])
                if spec['schema']==2:
                    self.assertEqual(0 if spec.get('variation') in {'uncaptured-declared','nested-unsupported'} else 1,len(result['summary'][wid]['captured']))
                revoked_history=spec.get('variation')=='captured-current-revoked'
                if revoked_history:
                    self.assertEqual([{'kind':'verified-revoked-history-premise','required':spec.get('required',False),'parent_work':'c2-parent','child_work':'c2-parent-child'}],result['stages'])
                if not spec.get('drift') and not (spec.get('required') and spec.get('owner')=='child-intent') and spec.get('parent_mode','local')=='local' and not (revoked_history and spec.get('required')):
                    self.assertTrue(all(row['baseline_equal'] for row in result['summary'].values() if row['state']!='completed' and row['mode']=='local'),'valid equal baseline prerequisite')
            return result

        def p2_local_success(self,target,fixture,*,frontier=None):
            from hv2ref.work import WorkStore,snapshot as project_snapshot
            product=self.product();preview=self.transition(target);initial=snapshot(target)
            truth={name:value for name,value in initial.items() if name.startswith(('.hrn/intents/','.hrn/work/'))}
            expected_ids=sorted(wid for wid,row in fixture['summary'].items() if row['state']!='completed' and row['mode']=='local')
            # Serialize then reload the exact caller-owned request before a new child executes.
            request_path=self.base/(target.name+'-restart-request.json');write_file(request_path,canonical(preview))
            if frontier:self.p2_b_advance(target,frontier,preview)
            preview=json.loads(request_path.read_bytes())
            code,data,_=self.call(target,self.apply_args(target,preview,recover=frontier is not None),preview['request'])
            self.assertEqual(0,code,data);result=json.loads(data)
            self.assertEqual({'classification':'verified','work_ids':expected_ids,'observation':'actual project snapshot'} if expected_ids else {'classification':'not-applicable','work_ids':[],'reason':'no unfinished selected local Work'},result['transition_content_verification'])
            state=product.verify_workspace_product(target)
            current=project_snapshot(target,verified_launcher_sha256=state['launcher_sha256'],verified_inventory_id='entry-1')
            self.assertEqual(fixture['snapshot'],current,'actual S6 project snapshot equals immutable OLD snapshot')
            self.assertEqual(truth,{name:value for name,value in snapshot(target).items() if name.startswith(('.hrn/intents/','.hrn/work/'))})
            graphs=WorkStore(target)._all()
            for wid,row in fixture['summary'].items():
                self.assertEqual(row['state'],graphs[wid]['state']);self.assertEqual(row['selection'],graphs[wid]['current']['selection_ref'])
            before=snapshot(target);code,data,_=self.call(target,self.apply_args(target,preview,recover=True),preview['request'])
            self.assertEqual(0,code,data);self.assertEqual('replayed',json.loads(data)['classification']);self.assertEqual(before,snapshot(target))
            self.assertEqual(fixture['snapshot'],project_snapshot(target,verified_launcher_sha256=state['launcher_sha256'],verified_inventory_id='entry-1'))

        def p2_c2_case(self,index):
            from hv2ref.errors import ContractError
            spec=P2_C2_ROWS[index];target=self.old_target();fixture=self.p2_local_graph(target,spec)
            kind=spec['kind'];required=spec.get('required',False);path=spec.get('path');owner=spec.get('owner','');variation=spec.get('variation')
            old_refusal=fixture['outcome']=='old-reference-construction-refusal'
            collision=required and path in {'colvia','colvia/leaf'} and not owner.startswith('child')
            captured=required and owner.startswith('child') and variation not in {'uncaptured-declared','captured-scope-only'} and path in {'colvia','colvia/leaf'}
            refuse=bool(spec.get('drift') or kind=='scope' or collision or captured)
            if old_refusal:
                self.assertTrue(required and path in {'hv2','hv2/leaf','HV2'})
                self.assertEqual('HV2-WORK-RECORD',fixture['boundary']['code']);self.assertTrue(fixture['boundary']['preserved'])
                self.assertFalse((target/'.hrn/product/receipts/entry-transition.json').exists())
            elif refuse:
                before=snapshot(target)
                with self.assertRaises(ContractError) as caught:self.transition(target)
                self.assertEqual('HV2-WORKSPACE-PRODUCT',caught.exception.code)
                if collision:self.assertEqual('preexisting launcher or alias is not owned',caught.exception.message)
                elif captured:
                    self.assertEqual("entry path dependency in selected local parent Work: c2-parent; captured child Work IDs: ['c2-parent-child']",caught.exception.message)
                elif kind=='scope':self.assertEqual('entry path dependency in selected local Work: '+('c2-parent' if spec['schema']==2 else 'c2-local'),caught.exception.message)
                else:
                    expected=sorted(wid for wid,row in fixture['summary'].items() if row['state']!='completed' and not row['baseline_equal'])
                    self.assertEqual('entry transition selected local baseline differs: '+repr(expected)+'; no transition receipt has been published',caught.exception.message)
                self.assertEqual(before,snapshot(target));self.assertFalse((target/'.hrn/product/receipts/entry-transition.json').exists())
            else:self.p2_local_success(target,fixture,frontier=spec.get('frontier'))
            if old_refusal or refuse:
                positive=copy.deepcopy(spec);positive['drift']=False
                if kind=='scope':positive['path']='a'
                if required:positive['required']=False
                other=self.old_target('positive');good=self.p2_local_graph(other,positive)
                self.assertEqual('constructed',good['outcome']);self.p2_local_success(other,good)

        def p2_c3_fixture(self,target,spec,phase='build',generation='old'):
            aux=self.base/(target.name+'-worker-fixture')
            if phase=='build':aux.mkdir()
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B','-c',P2_C3_FIXTURE_PROGRAM,
                paths['controls'],ctx['invocation_path'],ctx['invocation_sha256'],target,generation,phase,aux/'state.json'),'worker-fixture',spec)
            _,data=self.finish(child,log,timeout=150);result=json.loads(data)
            self.assertEqual(('verified-worker-fixture',generation,phase),(result['kind'],result['generation'],result['phase']))
            self.assertEqual((child.pid,os.getpgrp()),(result['pid'],result['pgid']))
            return result

        def p2_c3_target(self,name,generation='old'):
            if generation=='old':return self.old_target(name)
            target=self.directory(name);write_file(target/'a',b'before\n',0o644);self.new_init(target);return target

        def p2_c3_execute(self,target,spec,execution,executor):
            if executor=='verified-api-new':
                output=self.p2_c3_fixture(target,{**spec,'execution':execution},'execute','new')['result']
                return output['exit'],output['output']
            self.assertIn(executor,{'installed-old','installed-new'})
            code,data,_=self.call(target,execution['argv'],execution['request'],entry=executor)
            return code,json.loads(data)

        def p2_c3_transition(self,target,spec,fixture):
            initial=snapshot(target);truth={k:v for k,v in initial.items() if k.startswith(('.hrn/intents/','.hrn/work/'))};git={k:v for k,v in initial.items() if k=='.git' or k.startswith('.git/')}
            preview=self.transition(target);frontier=spec.get('frontier','normal')
            if frontier!='normal':self.p2_b_advance(target,frontier,preview)
            code,data,_=self.call(target,self.apply_args(target,preview,recover=frontier!='normal'),preview['request']);self.assertEqual(0,code,data)
            result=json.loads(data);self.assertEqual({'classification':'not-applicable','work_ids':[],'reason':'no unfinished selected local Work'},result['transition_content_verification'])
            after=snapshot(target);self.assertEqual(truth,{k:v for k,v in after.items() if k.startswith(('.hrn/intents/','.hrn/work/'))});self.assertEqual(git,{k:v for k,v in after.items() if k=='.git' or k.startswith('.git/')})
            observed=self.p2_c3_fixture(target,spec,'observe','new');self.assertEqual(fixture['summary'],observed['summary'])
            before=snapshot(target);code,data,_=self.call(target,self.apply_args(target,preview,recover=True),preview['request']);self.assertEqual(0,code,data);self.assertEqual('replayed',json.loads(data)['classification']);self.assertEqual(before,snapshot(target))
            return preview

        def p2_c3_case(self,index):
            from hv2ref.errors import ContractError
            spec=P2_C3_ROWS[index];kind=spec['kind'];generation=spec.get('generation','old')
            if kind=='negative':
                # A separate valid counterpart executes the same semantic writer first.
                positive=self.p2_c3_target('positive',generation);positive_spec={**spec,'negative':None}
                self.p2_c3_fixture(positive,positive_spec,generation=generation)
                execution=self.p2_c3_fixture(positive,positive_spec,'request',generation)['result']
                code,result=self.p2_c3_execute(positive,positive_spec,execution,'installed-'+generation);self.assertEqual(0,code,result);self.assertEqual('review',result['state'])
            target=self.p2_c3_target('target',generation);fixture=self.p2_c3_fixture(target,spec,generation=generation)
            if kind in {'selected-orphan','preservation'}:
                if kind=='selected-orphan':self.assertEqual('active' if spec['state'] in {'orphan-revision','baseline-refreshed'} else spec['state'],fixture['summary']['state'])
                else:
                    self.assertEqual('active',fixture['summary']['state'])
                    if spec['orphan']=='revision':self.assertIn('old-result',fixture['summary']['revisions'])
                    elif spec['orphan']=='rebind':self.assertIn('old-unselected-rebind',fixture['summary']['revisions'])
                    else:self.assertNotIn('old-result',fixture['summary']['revisions']);self.assertEqual(2,len(fixture['summary']['manifests']))
                self.assertEqual([],fixture['summary']['pending_decisions']);self.assertEqual([],fixture['summary']['pending_selections'])
                self.p2_c3_transition(target,spec,fixture);return
            if kind=='pending':
                preview=self.transition(target);pending=self.p2_c3_fixture(target,spec,'pending')
                self.assertTrue(pending['summary']['pending_decisions'] or pending['summary']['pending_selections']);before=snapshot(target)
                if spec['invocation']=='recover':
                    self.assertIsNone(self.product()._workspace_observe(target,allow_pending=True)['pending'])
                    self.assertFalse((target/'.hrn/product/receipts/entry-transition.json').exists())
                if spec['invocation']=='preview':
                    with self.assertRaises(ContractError) as caught:self.transition(target)
                    code,message=caught.exception.code,caught.exception.message
                else:
                    rc,data,_=self.call(target,self.apply_args(target,preview,recover=spec['invocation']=='recover'),preview['request']);self.assertEqual(65,rc,data);error=json.loads(data);code,message=error['code'],error['message']
                expected='no pending lifecycle to recover' if spec['invocation']=='recover' else 'pending Work blocks lifecycle'
                self.assertEqual(('HV2-WORKSPACE-PRODUCT',expected),(code,message));self.assertEqual(before,snapshot(target))
                recovered=self.p2_c3_fixture(target,spec,'recover');self.assertEqual([],recovered['summary']['pending_decisions']);self.assertEqual([],recovered['summary']['pending_selections'])
                self.p2_c3_transition(target,spec,recovered);return
            if kind=='old-proof':
                preview=self.p2_c3_transition(target,spec,fixture)
                if spec['replay']:
                    code,data,_=self.call(target,self.apply_args(target,preview,recover=True),preview['request']);self.assertEqual(0,code,data)
                execution=self.p2_c3_fixture(target,spec,'request','new')['result'];before=snapshot(target)
                code,result=self.p2_c3_execute(target,spec,execution,spec['executor']);self.assertEqual(65,code,result)
                expected=('HV2-WORK-RECORD','active binding changed') if spec['operation']=='old-ticket' else ('HV2-WORK-CONTENT','commit lacks verified executable managed launcher')
                self.assertEqual(expected,(result['code'],result['message']));self.assertEqual(before,snapshot(target));return
            if kind=='new-baseline':
                self.p2_c3_transition(target,spec,fixture)
                refreshed=self.p2_c3_fixture(target,spec,'refresh','new');self.assertEqual('active',refreshed['summary']['state']);self.assertNotEqual(fixture['summary']['head'],refreshed['summary']['head'])
                execution=refreshed['result'];before=snapshot(target);code,result=self.p2_c3_execute(target,spec,execution,spec['executor']);self.assertEqual(0,code,result);self.assertEqual('review',result['state'])
                after=snapshot(target);self.assertEqual({k:v for k,v in before.items() if not k.startswith('.hrn/work/')},{k:v for k,v in after.items() if not k.startswith('.hrn/work/')})
                current=result['selections'][result['current']['selection_ref']['id']];revision=result['revisions'][current['revision_ref']['id']];self.assertEqual('new-result',revision['record_id']);return
            self.assertEqual('negative',kind);execution=self.p2_c3_fixture(target,spec,'request',generation)['result'];before=snapshot(target)
            code,result=self.p2_c3_execute(target,spec,execution,'installed-'+generation);self.assertEqual(65,code,result)
            expected={
                'worker-missing':('HV2-WORK-RECORD','worker result requires explicit linked worktree'),
                'worker-control':('HV2-WORK-RECORD','worker must be a registered linked worktree'),
                'worker-dirty':('HV2-WORK-RECORD','worker bytes differ from committed result'),
                'worker-diverged':('HV2-WORK-RECORD','worker HEAD differs from candidate'),
                'retention-missing':('HV2-WORK-CONTENT','Git content probe failed: show-ref'),
                'control-drift':('HV2-WORK-RECORD','control differs from worker baseline; human baseline refresh required')}[spec['negative']]
            self.assertEqual(expected,(result['code'],result['message']));self.assertEqual(before,snapshot(target))

        def p2_new_counterpart(self,name='new2-source',*,same=False):
            source=self.directory(name);candidate=self.product().workspace_candidate(candidate_source)
            for member,data in candidate['payload'].items():write_file(source/member,data,0o755 if member=='colvia' else 0o644)
            if not same:
                with (source/'README.md').open('ab') as handle:handle.write(b'\nSynthetic P2 same-window lifecycle counterpart.\n')
            value=self.product().workspace_candidate(source)
            self.assertEqual(P2_RELEASE_ID if same else P2_C4_MAP['new2_id'],value['release_ref']['id'])
            self.assertEqual(P2_RELEASE_SHA256 if same else P2_C4_MAP['new2_sha256'],value['release_ref']['sha256'])
            return source

        def p2_c4_base(self,history):
            if history=='fresh':target=self.directory('target');self.new_init(target);transition=None
            else:
                if history=='old-counterpart-history':target,other,old_result=self.old_history_target('target');self.verify_counterpart(other,old_result)
                else:target=self.old_target()
                if history=='local':self.old_local(target)
                transition=self.transition(target)
                code,data,_=self.call(target,self.apply_args(target,transition),transition['request'])
                self.assertEqual(0,code,data)
            self.assertFalse((target/'hv2').exists());self.assertEqual(P2_RELEASE_ID,self.product()._workspace_observe(target)['binding']['active_release']['id'])
            return target,transition

        def p2_switch_args(self,target,preview,source,*,executor='new-source',recover=False):
            action=preview['request']['action'];args=self.p2_lifecycle_prefix(target,executor,action)
            args+=['--apply','--input','-','--confirm',preview['confirm_token']]
            if source is not None:args+=['--source',str(source)]
            if recover:args+=['--recover']
            return args

        def p2_c4_second(self,target,source,*,executor='new-source'):
            product=self.product();preview=product.workspace_switch_preview(target,action='update',source=source,operation_id='second-new',created_at=FIXTURE_TIME)
            self.assertEqual([],preview['request']['remove']);before=snapshot(target)
            code,data,_=self.call(target,self.p2_switch_args(target,preview,source,executor=executor),preview['request'],entry=executor)
            self.assertEqual(0,code,data);self.assertEqual('updated',json.loads(data)['classification'])
            self.assertEqual(before['a'],snapshot(target)['a']) if 'a' in before else None
            state=product._workspace_observe(target);self.assertIsNone(state['pending']);self.assertEqual(P2_C4_MAP['new2_id'],state['binding']['active_release']['id'])
            self.assertEqual(P2_RELEASE_ID,state['binding']['prior_release']['id']);self.assertFalse((target/'hv2').exists())
            return preview

        def p2_plain_audit(self,target,expected):
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B',candidate_source/'tests/fixtures/product_plain_auditor.py',target),'p2-plain-auditor')
            _,data=self.finish(child,log,timeout=30,expected=expected);return json.loads(data)

        def p2_detach_args(self,target,preview,*,recover=False):
            args=['--source-checkout','detach','--profile','entry-1','--target',target,'--apply','--input','-','--confirm',preview['confirm_token']]
            if recover:args+=['--recover']
            return args

        def p2_detach_receipt(self,plan):
            return {'record_type':'lifecycle-receipt','schema_version':3,'operation_id':plan['operation_id'],'plan':plan,
                'prior_binding_ref':plan['expected_binding_ref'],'result_binding_ref':None}

        def p2_c4_detach_fixture(self):
            target,_=self.p2_c4_base('transition');other=self.p2_new_counterpart();self.p2_c4_second(target,other)
            preview=self.product().workspace_detach_preview(target,operation_id='entry-detach',created_at=FIXTURE_TIME)
            self.assertEqual(3,preview['request']['schema_version'])
            self.assertEqual(sorted(P2_C4_MAP['files'],key=lambda n:n.encode()),[e['path'] for e in preview['request']['remove']])
            for entry in preview['request']['remove']+preview['request']['preserve']:
                raw=(target/entry['path']).read_bytes();self.assertEqual((len(raw),sha(raw)),(entry['size_bytes'],entry['sha256']))
            return target,preview

        def p2_c4_detach_frontier(self,spec):
            target,preview=self.p2_c4_detach_fixture();initial=snapshot(target)
            code,data,events=self.call(target,self.p2_detach_args(target,preview),preview['request'],fault={k:spec[k] for k in ('event','path','occurrence')}|{'write_bytes':None})
            self.assertEqual(-signal.SIGKILL,code,data);rows=self.event_rows(events)
            self.assertEqual((spec['event'],spec['path']),(rows[-1]['event'],rows[-1]['path']))
            self.assertEqual(1,sum(r['event']==spec['event'] and r['path']==spec['path'] for r in rows))
            raw=canonical(self.p2_detach_receipt(preview['request']));expected=dict(initial);expected['.hrn/detached.json']=('file',0o644,len(raw),sha(raw))
            for name in spec['removed_files']+spec['removed_directories']:expected.pop(name)
            self.assertEqual(expected,snapshot(target))
            complete=len(spec['removed_files'])==len(P2_C4_MAP['files']) and len(spec['removed_directories'])==len(P2_C4_MAP['directories'])
            before=snapshot(target);native=self.product().workspace_detached_status(target);plain=self.p2_plain_audit(target,0 if complete else 14)
            self.assertEqual('detached' if complete else 'partial',native['classification']);self.assertEqual(native['classification'],plain['classification'])
            self.assertEqual(P2_C4_MAP['files'][len(spec['removed_files']):],plain['remaining_files']);self.assertEqual(P2_C4_MAP['directories'][len(spec['removed_directories']):],plain['remaining_directories']);self.assertEqual(before,snapshot(target))
            code,data,_=self.call(target,self.p2_detach_args(target,preview,recover=True),preview['request']);self.assertEqual(0,code,data)
            final=dict(initial);final['.hrn/detached.json']=('file',0o644,len(raw),sha(raw))
            for name in P2_C4_MAP['files']+P2_C4_MAP['directories']:final.pop(name)
            self.assertEqual(final,snapshot(target));self.assertEqual('detached',self.p2_plain_audit(target,0)['classification'])
            code,data,events=self.call(target,self.p2_detach_args(target,preview,recover=True),preview['request']);self.assertEqual(0,code,data);self.assertTrue(json.loads(data)['replayed']);self.assertEqual(final,snapshot(target))
            self.assertFalse(any(r['event']=='lock-attempt' for r in self.event_rows(events)))

        def p2_c4_detach_negative(self,spec):
            from hv2ref.errors import ContractError,InjectedCrash
            target,preview=self.p2_c4_detach_fixture();product=self.product()
            with self.assertRaises(InjectedCrash) as caught:product.workspace_detach_apply(target,preview['request'],confirm_token=preview['confirm_token'],inject_at='after-receipt')
            self.assertEqual('after-receipt',caught.exception.point)
            self.assertEqual('partial',self.p2_plain_audit(target,14)['classification'])
            receipt_path=target/'.hrn/detached.json';receipt=json.loads(receipt_path.read_bytes());plan=receipt['plan'];case=spec['case'];message=None
            if case=='outer-schema':receipt['schema_version']=2;message='detach receipt does not bind plan'
            elif case=='inner-schema':plan['schema_version']=2;message='detach removal outside managed product'
            elif case=='boolean-schema':plan['schema_version']=True;message='detach plan identity/format'
            elif case=='missing-member':plan['remove']=[e for e in plan['remove'] if e['path']!='colvia'];message='detach incomplete removal/binding set'
            elif case=='reversed-members':plan['remove'].reverse();message='detach inventory order/alias'
            elif case=='duplicate-member':plan['remove'].insert(0,copy.deepcopy(plan['remove'][0]));message='detach inventory order/alias'
            elif case=='changed-member-digest':next(e for e in plan['remove'] if e['path']=='colvia')['sha256']='0'*64;message='detach launcher is not bound to a removed release'
            elif case=='file-gap':(target/P2_C4_MAP['files'][2]).unlink();message='not an exact detach file-removal prefix'
            elif case=='directory-gap':
                for name in P2_C4_MAP['files']:(target/name).unlink()
                # A leaf other than the first is removable yet violates the exact directory suffix.
                dirs=P2_C4_MAP['directories'];chosen=next(n for n in dirs[1:] if not any(other.startswith(n+'/') for other in dirs))
                (target/chosen).rmdir();message='not an exact detach directory-removal prefix'
            elif case=='unknown-directory':(target/'.hrn/product/foreign').mkdir();message='unknown detach member; preserve'
            elif case=='unknown-file':write_file(target/'.hrn/product/foreign',b'synthetic foreign\n');message='unknown detach member; preserve'
            elif case in {'changed-remaining','empty-remaining'}:
                (target/'colvia').write_bytes(b'foreign\n' if case=='changed-remaining' else b'');message='detach remaining bytes changed; preserve'
            elif case=='retired-entry':write_file(target/'hv2',b'project-owned retired entry\n');message="schema-3 detach or completed-detach replay: retired entry collision; preserve project occupants: ['hv2']"
            elif case=='linked-remaining':
                (target/'colvia').unlink();(target/'colvia').symlink_to('a');message='unsupported file type: colvia'
            else:self.assertEqual('noncanonical-receipt',case)
            if case in {'outer-schema','inner-schema','boolean-schema','missing-member','reversed-members','duplicate-member','changed-member-digest'}:receipt_path.write_bytes(canonical(receipt))
            if case=='noncanonical-receipt':receipt_path.write_bytes(b' '+receipt_path.read_bytes())
            before=snapshot(target)
            with self.assertRaises(ContractError) as caught:product.workspace_detached_status(target)
            if message is not None:self.assertEqual(message,caught.exception.message)
            else:self.assertEqual('HV2-JSON-NONCANONICAL',caught.exception.code)
