        def p2_c4_collision(self,spec):
            from hv2ref.errors import ContractError,InjectedCrash
            target,_=self.p2_c4_base('transition');other=self.p2_new_counterpart();second=self.p2_c4_second(target,other);product=self.product();operation=spec['operation'];preview=None
            if operation in {'update-preview','update-apply','update-recovery'}:
                preview=product.workspace_switch_preview(target,action='update',source=candidate_source,operation_id='collision-update',created_at=FIXTURE_TIME)
                if operation=='update-recovery':
                    with self.assertRaises(InjectedCrash):product.workspace_switch_apply(target,preview['request'],confirm_token=preview['confirm_token'],source=candidate_source,inject_at='after-receipt')
            elif operation=='rollback-preview':preview=product.workspace_switch_preview(target,action='rollback',source=None,operation_id='collision-rollback',created_at=FIXTURE_TIME)
            elif operation in {'detach-preview','detach-apply'}:preview=product.workspace_detach_preview(target,operation_id='collision-detach',created_at=FIXTURE_TIME)
            elif operation=='repair-preview':
                (target/'colvia').chmod(0o600)
                preview=product.workspace_repair_preview(other,target,self.base/'repair-backup',operation_id='collision-repair',created_at=FIXTURE_TIME)
            self.p2_c4_occupant(target,spec['occupant']);before=snapshot(target)
            if operation in {'status','doctor'}:
                code,data,_=self.call(target,['--source-checkout',operation,'--target',target]);self.assertEqual(12,code,data);result=json.loads(data)
                self.assertEqual('conflict',result['classification']);self.assertFalse(result['lifecycle_ready']);self.assertEqual(['HV2' if spec['occupant']=='case-alias' else 'hv2'],result['retired_entry_collision']['observed_names'])
            elif operation in {'update-apply','update-recovery','detach-apply','completed-replay'}:
                if operation=='completed-replay':args=self.p2_switch_args(target,second,other);request=second['request']
                elif operation=='detach-apply':args=self.p2_detach_args(target,preview);request=preview['request']
                else:args=self.p2_switch_args(target,preview,candidate_source,recover=operation=='update-recovery');request=preview['request']
                code,data,_=self.call(target,args,request);self.assertEqual(65,code,data);result=json.loads(data);self.assertEqual('HV2-WORKSPACE-PRODUCT',result['code']);self.assertIn('retired entry collision; preserve project occupants:',result['message'])
            else:
                with self.assertRaises(ContractError) as caught:
                    if operation in {'update-preview','rollback-preview'}:product.workspace_switch_preview(target,action=preview['request']['action'],source=candidate_source if operation=='update-preview' else None,operation_id=preview['request']['operation_id'],created_at=FIXTURE_TIME)
                    elif operation=='detach-preview':product.workspace_detach_preview(target,operation_id='collision-detach',created_at=FIXTURE_TIME)
                    else:self.assertEqual('repair-preview',operation);product.workspace_repair_preview(other,target,self.base/'repair-backup',operation_id='collision-repair',created_at=FIXTURE_TIME)
                self.assertEqual('HV2-WORKSPACE-PRODUCT',caught.exception.code);self.assertIn('retired entry collision; preserve project occupants:',caught.exception.message)
            self.assertEqual(before,snapshot(target));self.assertFalse((self.base/'repair-backup').exists())

        def p2_c4_api_seam(self,target,source,preview,kind,moment):
            child,log=self.spawn((ctx['runtime_path'],'-I','-S','-B','-c',P2_C4_SAME_ENTRY_PROGRAM,
                paths['controls'],ctx['invocation_path'],ctx['invocation_sha256'],target,source,kind,moment),'fixed-api-interleaving',preview)
